(106, 'widget_block', 'a:7:{i:2;a:1:{s:7:\"content\";s:19:\"<!-- wp:search /-->\";}i:3;a:1:{s:7:\"content\";s:170:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h5>نوشته‌های تازه</h5><!-- /wp:heading --><!-- wp:latest-posts /--></div><!-- /wp:group -->\";}i:4;a:1:{s:7:\"content\";s:242:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h5>آخرین دیدگاه‌ها</h5><!-- /wp:heading --><!-- wp:latest-comments {\"displayAvatar\":false,\"displayDate\":false,\"displayExcerpt\":false} /--></div><!-- /wp:group -->\";}i:5;a:1:{s:7:\"content\";s:159:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>بایگانی‌ها</h2><!-- /wp:heading --><!-- wp:archives /--></div><!-- /wp:group -->\";}i:6;a:1:{s:7:\"content\";s:155:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>دسته‌ها</h2><!-- /wp:heading --><!-- wp:categories /--></div><!-- /wp:group -->\";}s:12:\"_multiwidget\";i:1;i:8;a:1:{s:7:\"content\";s:4869:\"<!-- ===================================================================\n     فوتر — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن (پایین‌ترین بلاک صفحه).\n     کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen6-footer {\n    --ink: #0F2A1E;\n    --muted: #9FB3A8;\n    --line: rgba(244,247,245,0.12);\n    --bg: #0B1F17;\n    --brand: #159A5B;\n    --brand-bright: #4CD787;\n    --off: #F4F7F5;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--off);\n    padding: 4vw 6vw 2vw;\n    box-sizing: border-box;\n  }\n  .aen6-footer * { box-sizing: border-box; }\n\n  .aen6-top {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.2fr 0.8fr 1fr 1fr;\n    gap: 2.4rem;\n    padding-bottom: 2.6rem;\n  }\n\n  .aen6-brand-name {\n    font-weight: 800;\n    font-size: 1.15rem;\n    color: var(--off);\n    margin: 0 0 0.9rem;\n  }\n  .aen6-brand-name span { color: var(--brand-bright); }\n\n  .aen6-top p.aen6-desc {\n    font-size: 0.9rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n    max-width: 22rem;\n  }\n\n  .aen6-col h4 {\n    font-size: 0.92rem;\n    font-weight: 700;\n    color: var(--off);\n    margin: 0 0 1.1rem;\n  }\n\n  .aen6-col ul {\n    list-style: none;\n    margin: 0;\n    padding: 0;\n    display: flex;\n    flex-direction: column;\n    gap: 0.75rem;\n  }\n  .aen6-col a {\n    color: var(--muted);\n    text-decoration: none;\n    font-size: 0.88rem;\n    transition: color .15s ease;\n  }\n  .aen6-col a:hover { color: var(--brand-bright); }\n\n  .aen6-col .aen6-cta a {\n    color: var(--brand-bright);\n    font-weight: 700;\n  }\n\n  .aen6-contact li {\n    font-size: 0.88rem;\n    color: var(--muted);\n    line-height: 1.85;\n  }\n  .aen6-contact li b {\n    display: block;\n    color: var(--off);\n    font-weight: 700;\n    font-size: 0.85rem;\n    margin-bottom: 0.15rem;\n  }\n  .aen6-contact li a {\n    color: var(--muted);\n    text-decoration: none;\n    direction: ltr;\n    display: inline-block;\n  }\n  .aen6-contact li a:hover { color: var(--brand-bright); }\n\n  .aen6-bottom {\n    max-width: 1180px;\n    margin: 0 auto;\n    border-top: 1px solid var(--line);\n    padding-top: 1.4rem;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 0.8rem;\n    font-size: 0.8rem;\n    color: var(--muted);\n  }\n\n  @media (max-width: 900px) {\n    .aen6-top { grid-template-columns: 1fr 1fr; }\n  }\n  @media (max-width: 560px) {\n    .aen6-top { grid-template-columns: 1fr; text-align: center; }\n    .aen6-top p.aen6-desc { max-width: 100%; margin: 0 auto; }\n    .aen6-col ul { align-items: center; }\n    .aen6-bottom { justify-content: center; text-align: center; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&amp;display=swap\" rel=\"stylesheet\">\n\n<footer class=\"aen6-footer\">\n  <div class=\"aen6-top\">\n\n    <div class=\"aen6-brand\">\n      <div class=\"aen6-brand-name\">آبان انرژی <span>نوا</span></div>\n      <p class=\"aen6-desc\">\n        تولید، واردات و نصب شارژرهای خودروی برقی، همراه با پلتفرم نرم‌افزاری\n        مدیریت شارژ سازگار با استاندارد OCPP.\n      </p>\n    </div>\n\n    <div class=\"aen6-col\">\n      <h4>دسترسی سریع</h4>\n      <ul>\n        <li><a href=\"/\">خانه</a></li>\n        <li class=\"aen6-cta\"><a href=\"/start-charging/\">شروع شارژر</a></li>\n        <li><a href=\"#\">اتصال شارژر شما</a></li>\n        <li><a href=\"/contact/\">تماس با ما</a></li>\n      </ul>\n    </div>\n\n    <div class=\"aen6-col\">\n      <h4>تماس با ما</h4>\n      <ul class=\"aen6-contact\">\n        <li>\n          <b>تلفن</b>\n          <a href=\"tel:+982166649792\">021 66649792</a>\n        </li>\n        <li>\n          <b>فروش</b>\n          <a href=\"tel:+989193341696\">0919 334 1696</a>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"aen6-col\">\n      <h4>آدرس و ساعت کاری</h4>\n      <ul class=\"aen6-contact\">\n        <li>\n          <b>آدرس</b>\n          مهرآباد جنوبی، خیابان کوسه‌لو، تهران، ایران\n        </li>\n        <li>\n          <b>ساعت کاری</b>\n          شنبه تا چهارشنبه، ۸ تا ۱۶\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <div class=\"aen6-bottom\">\n    <span>© ۱۴۰۵ آبان انرژی نوا. تمامی حقوق محفوظ است.</span>\n    <span>ساخته‌شده برای آینده‌ی شارژ هوشمند</span>\n  </div>\n</footer>\";}}', 'on'),
