(236, 'kadence_blocks_prophecy', '{\"firstTime\":false,\"isSubmitted\":true,\"isComplete\":true,\"context\":\"kadence\",\"companyName\":\"Aban Energy Nova\",\"entityType\":\"COMPANY\",\"locationType\":\"Business Address\",\"locationInput\":\"Mehrabad Jonubi, Kuseh Lu St., Motalebbi st. No. 26, Unit 3, Teharn, Iran\",\"location\":\"Business Address: Mehrabad Jonubi, Kuseh Lu St., Motalebbi st. No. 26, Unit 3, Teharn, Iran\",\"industry\":\"EV charger for Electric Vehicle\",\"missionStatement\":\"Aban Energy Nova import, produce and install EV charger for Electric Vehicle in MENA region.\\nWe are installing high quality chrger unit for commercial and residential towers and apartments. \\nThe shopping mall, gas station in the intercity roads and other sites are also considered to have EV charger. We install AC and DC charger.\",\"keywords\":[\"EV charger\",\"Electric Vehicle Charging Solutions\",\"High-Quality Charging Units\",\"Residential EV Chargers\",\"Commercial Charging Stations\",\"MENA Region EV Infrastructure\",\"EV Charger Installation\",\"Green Technology\",\"AC and DC Chargers\"],\"tone\":\"PROFESSIONAL\",\"privacyAgreement\":false,\"photoLibrary\":\"aiGenerated\",\"featuredImages\":[],\"backgroundImages\":[],\"customCollections\":[{\"label\":\"My Images\",\"value\":\"my-images\",\"galleries\":[{\"name\":\"featured\",\"isLocal\":true,\"images\":[]},{\"name\":\"background\",\"isLocal\":true,\"images\":[]}]}],\"verticals\":[],\"suggestedKeywords\":[\"Sustainable Energy Solutions\",\"Electric Mobility\"],\"suggestedKeywordsState\":\"success\",\"imageSearchQuery\":\"EV charger electric vehicle charging station AC charger DC charger commercial residential installation high quality energy solutions renewable energy infrastructure electric mobility MENA region shopping mall gas station intercity roads\",\"lang\":\"\",\"goals\":[\"services\",\"landing\"],\"style\":\"redwood\"}', 'auto'),
