(15, 1, '2025-12-20 18:28:09', '2025-12-20 14:58:09', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual {\n      order: -1;\n      position: static;\n      height: auto;\n      max-width: 320px;\n      margin: 0 auto 1.6rem;\n      display: flex;\n      flex-direction: column;\n      gap: 1rem;\n    }\n    .aen2-card {\n      position: static;\n      width: 100% !important;\n      max-width: 100% !important;\n    }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"/start-charging/\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'خانه', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-08-03 14:47:30', '2026-08-03 11:17:30', '', 0, 'http://abanenergynova.ir/?page_id=15', 0, 'page', '', 0),
(16, 1, '2025-12-20 18:28:09', '2025-12-20 14:58:09', '<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"className\":\"hestia-title\"} -->\n<h2 class=\"wp-block-heading hestia-title\">Send us a message</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<div class=\"contact-wrapper\">\n																			<div class=\"content\">\n			\n			  <form>\n			   <div class=\"form-group\">\n			    <input type=\"text\" id=\"fname\" name=\"firstname\" placeholder=\"Your name..\">\n			</div>\n			<div class=\"form-group\">\n			    <input type=\"text\" id=\"lname\" name=\"lastname\" placeholder=\"Your last name..\">\n			</div>\n			<div class=\"form-group\">\n			    <textarea id=\"subject\" name=\"subject\" placeholder=\"Write something..\" style=\"height:200px\"></textarea>\n			</div>\n			    <input type=\"submit\" value=\"Submit\">\n			\n			  </form>\n			</div>\n			</div>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"metadata\":{\"blockVisibility\":false}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":4,\"className\":\"hestia-title\",\"style\":{\"typography\":{\"fontSize\":18,\"textAlign\":\"right\"},\"color\":{\"text\":\"#3c4858\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-right hestia-title has-text-color\" style=\"color:#3c4858;font-size:18px\"><img class=\"wp-image-86\" style=\"width: 25px;\" src=\"http://abanenergynova.ir/wp-con