(388, 1, '2026-08-03 13:33:40', '2026-08-03 10:03:40', '{\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- ===================================================================\\n     \\u0641\\u0648\\u062a\\u0631 \\u2014 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627\\n     \\u0646\\u062d\\u0648\\u0647 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647: \\u06a9\\u0644 \\u0627\\u06cc\\u0646 \\u06a9\\u062f \\u0631\\u0648 \\u062f\\u0627\\u062e\\u0644 \\u06cc\\u06a9 \\u0648\\u06cc\\u062c\\u062a \\\"HTML\\\" \\u062f\\u0631 Elementor \\u06cc\\u0627\\n     \\u0628\\u0644\\u0627\\u06a9 \\\"Custom HTML\\\" \\u062f\\u0631 \\u06af\\u0648\\u062a\\u0646\\u0628\\u0631\\u06af \\u067e\\u06cc\\u0633\\u062a \\u06a9\\u0646 (\\u067e\\u0627\\u06cc\\u06cc\\u0646\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0628\\u0644\\u0627\\u06a9 \\u0635\\u0641\\u062d\\u0647).\\n     \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b self-contained \\u0627\\u0633\\u062a.\\n==================================================================== -->\\n\\n<style>\\n  .aen6-footer {\\n    --ink: #0F2A1E;\\n    --muted: #9FB3A8;\\n    --line: rgba(244,247,245,0.12);\\n    --bg: #0B1F17;\\n    --brand: #159A5B;\\n    --brand-bright: #4CD787;\\n    --off: #F4F7F5;\\n\\n    direction: rtl;\\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\\n    background: var(--bg);\\n    color: var(--off);\\n    padding: 4vw 6vw 2vw;\\n    box-sizing: border-box;\\n  }\\n  .aen6-footer * { box-sizing: border-box; }\\n\\n  .aen6-top {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    display: grid;\\n    grid-template-columns: 1.2fr 0.8fr 1fr 1fr;\\n    gap: 2.4rem;\\n    padding-bottom: 2.6rem;\\n  }\\n\\n  .aen6-brand-name {\\n    font-weight: 800;\\n    font-size: 1.15rem;\\n    color: var(--off);\\n    margin: 0 0 0.9rem;\\n  }\\n  .aen6-brand-name span { color: var(--brand-bright); }\\n\\n  .aen6-top p.aen6-desc {\\n    font-size: 0.9rem;\\n    line-height: 1.9;\\n    color: var(--muted);\\n    margin: 0;\\n    max-width: 22rem;\\n  }\\n\\n  .aen6-col h4 {\\n    font-size: 0.92rem;\\n    font-weight: 700;\\n    color: var(--off);\\n    margin: 0 0 1.1rem;\\n  }\\n\\n  .aen6-col ul {\\n    list-style: none;\\n    margin: 0;\\n    padding: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.75rem;\\n  }\\n  .aen6-col a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    font-size: 0.88rem;\\n    transition: color .15s ease;\\n  }\\n  .aen6-col a:hover { color: var(--brand-bright); }\\n\\n  .aen6-col .aen6-cta a {\\n    color: var(--brand-bright);\\n    font-weight: 700;\\n  }\\n\\n  .aen6-contact li {\\n    font-size: 0.88rem;\\n    color: var(--muted);\\n    line-height: 1.85;\\n  }\\n  .aen6-contact li b {\\n    display: block;\\n    color: var(--off);\\n    font-weight: 700;\\n    font-size: 0.85rem;\\n    margin-bottom: 0.15rem;\\n  }\\n  .aen6-contact li a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    direction: ltr;\\n    display: inline-block;\\n  }\\n  .aen6-contact li a:hover { color: var(--brand-bright); }\\n\\n  .aen6-bottom {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    border-top: 1px solid var(--line);\\n    padding-top: 1.4rem;\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    flex-wrap: wrap;\\n    gap: 0.8rem;\\n    font-size: 0.8rem;\\n    color: var(--muted);\\n  }\\n\\n  @media (max-width: 900px) {\\n    .aen6-top { grid-template-columns: 1fr 1fr; }\\n  }\\n  @media (max-width: 560px) {\\n    .aen6-top { grid-template-columns: 1fr; text-align: center; }\\n    .aen6-top p.aen6-desc { max-width: 100%; margin: 0 auto; }\\n    .aen6-col ul { align-items: center; }\\n    .aen6-bottom { justify-content: center; text-align: center; }\\n  }\\n</style>\\n\\n<link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\">\\n<link href=\\\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&amp;display=swap\\\" rel=\\\"stylesheet\\\">\\n\\n<footer class=\\\"aen6-footer\\\">\\n  <div class=\\\"aen6-top\\\">\\n\\n    <div class=\\\"aen6-brand\\\">\\n      <div class=\\\"aen6-brand-name\\\">\\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc <span>\\u0646\\u0648\\u0627</span></div>\\n      <p class=\\\"aen6-desc\\\">\\n        \\u062a\\u0648\\u0644\\u06cc\\u062f\\u060c \\u0648\\u0627\\u0631\\u062f\\u0627\\u062a \\u0648 \\u0646\\u0635\\u0628 \\u0634\\u0627\\u0631\\u0698\\u0631\\u0647\\u0627\\u06cc \\u062e\\u0648\\u062f\\u0631\\u0648\\u06cc \\u0628\\u0631\\u0642\\u06cc\\u060c \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645 \\u0646\\u0631\\u0645\\u200c\\u0627\\u0641\\u0632\\u0627\\u0631\\u06cc\\n        \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0634\\u0627\\u0631\\u0698 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0628\\u0627 \\u0627\\u0633\\u062a\\u0627\\u0646\\u062f\\u0627\\u0631\\u062f OCPP.\\n      </p>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u0633\\u0631\\u06cc\\u0639</h4>\\n      <ul>\\n        <li><a href=\\\"/\\\">\\u062e\\u0627\\u0646\\u0647</a></li>\\n        <li class=\\\"aen6-cta\\\"><a href=\\\"#\\\">\\u0634\\u0631\\u0648\\u0639 \\u0634\\u0627\\u0631\\u0698\\u0631</a></li>\\n        <li><a href=\\\"#\\\">\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0634\\u0627\\u0631\\u0698\\u0631 \\u0634\\u0645\\u0627</a></li>\\n        <li><a href=\\\"/contact/\\\">\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</a></li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u062a\\u0644\\u0641\\u0646</b>\\n          <a href=\\\"tel:+982166649792\\\">021 66649792</a>\\n        </li>\\n        <li>\\n          <b>\\u0641\\u0631\\u0648\\u0634</b>\\n          <a href=\\\"tel:+989193341696\\\">0919 334 1696</a>\\n        </li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u0622\\u062f\\u0631\\u0633 \\u0648 \\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u0622\\u062f\\u0631\\u0633</b>\\n          \\u0645\\u0647\\u0631\\u0622\\u0628\\u0627\\u062f \\u062c\\u0646\\u0648\\u0628\\u06cc\\u060c \\u062e\\u06cc\\u0627\\u0628\\u0627\\u0646 \\u06a9\\u0648\\u0633\\u0647\\u200c\\u0644\\u0648\\u060c \\u062a\\u0647\\u0631\\u0627\\u0646\\u060c \\u0627\\u06cc\\u0631\\u0627\\u0646\\n        </li>\\n        <li>\\n          <b>\\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</b>\\n          \\u0634\\u0646\\u0628\\u0647 \\u062a\\u0627 \\u0686\\u0647\\u0627\\u0631\\u0634\\u0646\\u0628\\u0647\\u060c \\u06f8 \\u062a\\u0627 \\u06f1\\u06f6\\n        </li>\\n      </ul>\\n    </div>\\n\\n  </div>\\n\\n  <div class=\\\"aen6-bottom\\\">\\n    <span>\\u00a9 \\u06f1\\u06f4\\u06f0\\u06f5 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627. \\u062a\\u0645\\u0627\\u0645\\u06cc \\u062d\\u0642\\u0648\\u0642 \\u0645\\u062d\\u0641\\u0648\\u0638 \\u0627\\u0633\\u062a.</span>\\n    <span>\\u0633\\u0627\\u062e\\u062a\\u0647\\u200c\\u0634\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647\\u200c\\u06cc \\u0634\\u0627\\u0631\\u0698 \\u0647\\u0648\\u0634\\u0645\\u0646\\u062f</span>\\n  </div>\\n</footer>\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:03:40\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '8418d284-f835-4859-9966-77bf2e34824b', '', '', '2026-08-03 13:33:40', '2026-08-03 10:03:40', '', 0, 'https://abanenergynova.ir/2026/08/03/8418d284-f835-4859-9966-77bf2e34824b/', 0, 'customize_changeset', '', 0),
(389, 1, '2026-08-03 13:34:56', '2026-08-03 10:04:56', '{\n    \"kadence::footer_top_columns\": {\n        \"value\": \"1\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:04:56\"\n    },\n    \"kadence::footer_top_layout\": {\n        \"value\": {\n            \"mobile\": \"row\",\n            \"tablet\": \"\",\n            \"desktop\": \"row\",\n            \"flag\": true\n        },\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:04:56\"\n    },\n    \"kadence::footer_middle_direction\": {\n        \"value\": {\n            \"mobile\": \"\",\n            \"tablet\": \"\",\n            \"desktop\": \"row\",\n            \"flag\": false\n        },\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:04:56\"\n    },\n    \"kadence::footer_items\": {\n        \"value\": {\n            \"top\": {\n                \"top_1\": [\n                    \"footer-widget1\"\n                ],\n                \"top_2\": [],\n                \"top_3\": [],\n                \"top_4\": [],\n                \"top_5\": []\n            },\n            \"middle\": {\n                \"middle_1\": [],\n                \"middle_2\": [],\n                \"middle_3\": [],\n                \"middle_4\": [],\n                \"middle_5\": []\n            },\n            \"bottom\": {\n                \"bottom_1\": [],\n                \"bottom_2\": [],\n                \"bottom_3\": [],\n                \"bottom_4\": [],\n                \"bottom_5\": []\n            },\n            \"flag\": true\n        },\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:04:56\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'e242544a-c94c-407a-b81e-78aa99b34974', '', '', '2026-08-03 13:34:56', '2026-08-03 10:04:56', '', 0, 'https://abanenergynova.ir/2026/08/03/e242544a-c94c-407a-b81e-78aa99b34974/', 0, 'customize_changeset', '', 0),
(367, 1, '2026-08-02 21:57:50', '2026-08-02 18:27:50', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"#\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"className\":\"col-md-5\"} -->\n<div class=\"wp-block-column col-md-5\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"right\"} -->\n<h2 class=\"wp-block-heading has-text-align-right\">در مورد آبان انرژی نوا</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">شرکت آبان انرژی نوادر سال 1404 برای واردات، تولید و نصب شارژهای خودروی برقی با بالاترین کیفیت تاسیس شد</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"col-md-6 col-md-offset1\"} -->\n<div class=\"wp-block-column col-md-6 col-md-offset1\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://abanenergynova.ir/wp-content/uploads/2025/12/eco-friendly-solar-panel-charging-station-for-electric-vehicles-outdoors.-9800036-1536x2048-1-768x1024.jpg\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-02 21:57:50', '2026-08-02 18:27:50', '', 15, 'https://abanenergynova.ir/?p=367', 0, 'revision', '', 0),
