(380, 1, '2026-08-03 12:35:45', '2026-08-03 09:05:45', '@import url(\'https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700&display=swap\');\nbody, .site-header, .main-navigation { font-family: \'Vazirmatn\', Tahoma, sans-serif !important; }\n\n.menu-cta a {\n  background: #159A5B;\n  color: #fff !important;\n  padding: 0.55rem 1.3rem;\n  border-radius: 8px;\n  font-weight: 700;\n  transition: background 0.15s ease;\n}\n.menu-cta a:hover {\n  background: #0E7A47;\n  color: #fff !important;\n}', 'kadence', '', 'publish', 'closed', 'closed', '', 'kadence', '', '', '2026-08-03 12:36:16', '2026-08-03 09:06:16', '', 0, 'https://abanenergynova.ir/2026/08/03/kadence/', 0, 'custom_css', '', 0),
