(385, 1, '2026-08-03 12:39:04', '2026-08-03 09:09:04', '{\n    \"site_icon\": {\n        \"value\": 384,\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 09:09:04\"\n    },\n    \"kadence::logo_width\": {\n        \"value\": {\n            \"size\": {\n                \"mobile\": \"\",\n                \"tablet\": \"\",\n                \"desktop\": 180\n            },\n            \"unit\": {\n                \"mobile\": \"px\",\n                \"tablet\": \"px\",\n                \"desktop\": \"px\"\n            },\n            \"flag\": true\n        },\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 09:09:04\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '8e53316c-671a-4c34-9a75-a05aa6a93cd7', '', '', '2026-08-03 12:39:04', '2026-08-03 09:09:04', '', 0, 'https://abanenergynova.ir/2026/08/03/8e53316c-671a-4c34-9a75-a05aa6a93cd7/', 0, 'customize_changeset', '', 0),
(386, 1, '2026-08-03 12:59:23', '2026-08-03 09:29:23', '{\n    \"kadence::nav_menu_locations[secondary]\": {\n        \"value\": 4,\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 09:29:23\"\n    },\n    \"kadence::nav_menu_locations[mobile]\": {\n        \"value\": 4,\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 09:29:23\"\n    },\n    \"kadence::nav_menu_locations[footer]\": {\n        \"value\": 4,\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 09:29:23\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '46f4f3d4-0981-4ee9-ae6e-d7d052323702', '', '', '2026-08-03 12:59:23', '2026-08-03 09:29:23', '', 0, 'https://abanenergynova.ir/2026/08/03/46f4f3d4-0981-4ee9-ae6e-d7d052323702/', 0, 'customize_changeset', '', 0),
(387, 1, '2026-08-03 13:31:23', '2026-08-03 10:01:23', '{\n    \"kadence::footer_items\": {\n        \"value\": {\n            \"top\": {\n                \"top_1\": [],\n                \"top_2\": [],\n                \"top_3\": [\n                    \"footer-widget1\"\n                ],\n                \"top_4\": [],\n                \"top_5\": []\n            },\n            \"middle\": {\n                \"middle_1\": [],\n                \"middle_2\": [],\n                \"middle_3\": [],\n                \"middle_4\": [],\n                \"middle_5\": []\n            },\n            \"bottom\": {\n                \"bottom_1\": [],\n                \"bottom_2\": [],\n                \"bottom_3\": [],\n                \"bottom_4\": [],\n                \"bottom_5\": []\n            },\n            \"flag\": false\n        },\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:01:11\"\n    },\n    \"sidebars_widgets[footer1]\": {\n        \"value\": [\n            \"block-8\"\n        ],\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:01:11\"\n    },\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- ===================================================================\\n     \\u0641\\u0648\\u062a\\u0631 \\u2014 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627\\n     \\u0646\\u062d\\u0648\\u0647 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647: \\u06a9\\u0644 \\u0627\\u06cc\\u0646 \\u06a9\\u062f \\u0631\\u0648 \\u062f\\u0627\\u062e\\u0644 \\u06cc\\u06a9 \\u0648\\u06cc\\u062c\\u062a \\\"HTML\\\" \\u062f\\u0631 Elementor \\u06cc\\u0627\\n     \\u0628\\u0644\\u0627\\u06a9 \\\"Custom HTML\\\" \\u062f\\u0631 \\u06af\\u0648\\u062a\\u0646\\u0628\\u0631\\u06af \\u067e\\u06cc\\u0633\\u062a \\u06a9\\u0646 (\\u067e\\u0627\\u06cc\\u06cc\\u0646\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0628\\u0644\\u0627\\u06a9 \\u0635\\u0641\\u062d\\u0647).\\n     \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b self-contained \\u0627\\u0633\\u062a.\\n==================================================================== -->\\n\\n<style>\\n  .aen6-footer {\\n    --ink: #0F2A1E;\\n    --muted: #9FB3A8;\\n    --line: rgba(244,247,245,0.12);\\n    --bg: #0B1F17;\\n    --brand: #159A5B;\\n    --brand-bright: #4CD787;\\n    --off: #F4F7F5;\\n\\n    direction: rtl;\\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\\n    background: var(--bg);\\n    color: var(--off);\\n    padding: 4vw 6vw 2vw;\\n    box-sizing: border-box;\\n  }\\n  .aen6-footer * { box-sizing: border-box; }\\n\\n  .aen6-top {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    display: grid;\\n    grid-template-columns: 1.2fr 0.8fr 1fr 1fr;\\n    gap: 2.4rem;\\n    padding-bottom: 2.6rem;\\n  }\\n\\n  .aen6-brand-name {\\n    font-weight: 800;\\n    font-size: 1.15rem;\\n    color: var(--off);\\n    margin: 0 0 0.9rem;\\n  }\\n  .aen6-brand-name span { color: var(--brand-bright); }\\n\\n  .aen6-top p.aen6-desc {\\n    font-size: 0.9rem;\\n    line-height: 1.9;\\n    color: var(--muted);\\n    margin: 0;\\n    max-width: 22rem;\\n  }\\n\\n  .aen6-col h4 {\\n    font-size: 0.92rem;\\n    font-weight: 700;\\n    color: var(--off);\\n    margin: 0 0 1.1rem;\\n  }\\n\\n  .aen6-col ul {\\n    list-style: none;\\n    margin: 0;\\n    padding: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.75rem;\\n  }\\n  .aen6-col a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    font-size: 0.88rem;\\n    transition: color .15s ease;\\n  }\\n  .aen6-col a:hover { color: var(--brand-bright); }\\n\\n  .aen6-col .aen6-cta a {\\n    color: var(--brand-bright);\\n    font-weight: 700;\\n  }\\n\\n  .aen6-contact li {\\n    font-size: 0.88rem;\\n    color: var(--muted);\\n    line-height: 1.85;\\n  }\\n  .aen6-contact li b {\\n    display: block;\\n    color: var(--off);\\n    font-weight: 700;\\n    font-size: 0.85rem;\\n    margin-bottom: 0.15rem;\\n  }\\n  .aen6-contact li a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    direction: ltr;\\n    display: inline-block;\\n  }\\n  .aen6-contact li a:hover { color: var(--brand-bright); }\\n\\n  .aen6-bottom {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    border-top: 1px solid var(--line);\\n    padding-top: 1.4rem;\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    flex-wrap: wrap;\\n    gap: 0.8rem;\\n    font-size: 0.8rem;\\n    color: var(--muted);\\n  }\\n\\n  @media (max-width: 900px) {\\n    .aen6-top { grid-template-columns: 1fr 1fr; }\\n  }\\n  @media (max-width: 560px) {\\n    .aen6-top { grid-template-columns: 1fr; text-align: center; }\\n    .aen6-top p.aen6-desc { max-width: 100%; margin: 0 auto; }\\n    .aen6-col ul { align-items: center; }\\n    .aen6-bottom { justify-content: center; text-align: center; }\\n  }\\n</style>\\n\\n<link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\">\\n<link href=\\\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\\\" rel=\\\"stylesheet\\\">\\n\\n<footer class=\\\"aen6-footer\\\">\\n  <div class=\\\"aen6-top\\\">\\n\\n    <div class=\\\"aen6-brand\\\">\\n      <div class=\\\"aen6-brand-name\\\">\\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc <span>\\u0646\\u0648\\u0627</span></div>\\n      <p class=\\\"aen6-desc\\\">\\n        \\u062a\\u0648\\u0644\\u06cc\\u062f\\u060c \\u0648\\u0627\\u0631\\u062f\\u0627\\u062a \\u0648 \\u0646\\u0635\\u0628 \\u0634\\u0627\\u0631\\u0698\\u0631\\u0647\\u0627\\u06cc \\u062e\\u0648\\u062f\\u0631\\u0648\\u06cc \\u0628\\u0631\\u0642\\u06cc\\u060c \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645 \\u0646\\u0631\\u0645\\u200c\\u0627\\u0641\\u0632\\u0627\\u0631\\u06cc\\n        \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0634\\u0627\\u0631\\u0698 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0628\\u0627 \\u0627\\u0633\\u062a\\u0627\\u0646\\u062f\\u0627\\u0631\\u062f OCPP.\\n      </p>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u0633\\u0631\\u06cc\\u0639</h4>\\n      <ul>\\n        <li><a href=\\\"/\\\">\\u062e\\u0627\\u0646\\u0647</a></li>\\n        <li class=\\\"aen6-cta\\\"><a href=\\\"#\\\">\\u0634\\u0631\\u0648\\u0639 \\u0634\\u0627\\u0631\\u0698\\u0631</a></li>\\n        <li><a href=\\\"#\\\">\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0634\\u0627\\u0631\\u0698\\u0631 \\u0634\\u0645\\u0627</a></li>\\n        <li><a href=\\\"/contact/\\\">\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</a></li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u062a\\u0644\\u0641\\u0646</b>\\n          <a href=\\\"tel:+982166649792\\\">021 66649792</a>\\n        </li>\\n        <li>\\n          <b>\\u0641\\u0631\\u0648\\u0634</b>\\n          <a href=\\\"tel:+989193341696\\\">0919 334 1696</a>\\n        </li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u0622\\u062f\\u0631\\u0633 \\u0648 \\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u0622\\u062f\\u0631\\u0633</b>\\n          \\u0645\\u0647\\u0631\\u0622\\u0628\\u0627\\u062f \\u062c\\u0646\\u0648\\u0628\\u06cc\\u060c \\u062e\\u06cc\\u0627\\u0628\\u0627\\u0646 \\u06a9\\u0648\\u0633\\u0647\\u200c\\u0644\\u0648\\u060c \\u062a\\u0647\\u0631\\u0627\\u0646\\u060c \\u0627\\u06cc\\u0631\\u0627\\u0646\\n        </li>\\n        <li>\\n          <b>\\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</b>\\n          \\u0634\\u0646\\u0628\\u0647 \\u062a\\u0627 \\u0686\\u0647\\u0627\\u0631\\u0634\\u0646\\u0628\\u0647\\u060c \\u06f8 \\u062a\\u0627 \\u06f1\\u06f6\\n        </li>\\n      </ul>\\n    </div>\\n\\n  </div>\\n\\n  <div class=\\\"aen6-bottom\\\">\\n    <span>\\u00a9 \\u06f1\\u06f4\\u06f0\\u06f4 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627. \\u062a\\u0645\\u0627\\u0645\\u06cc \\u062d\\u0642\\u0648\\u0642 \\u0645\\u062d\\u0641\\u0648\\u0638 \\u0627\\u0633\\u062a.</span>\\n    <span>\\u0633\\u0627\\u062e\\u062a\\u0647\\u200c\\u0634\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647\\u200c\\u06cc \\u0634\\u0627\\u0631\\u0698 \\u0647\\u0648\\u0634\\u0645\\u0646\\u062f</span>\\n  </div>\\n</footer>\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:01:23\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '786bddcf-ac83-456f-a092-af287e32628b', '', '', '2026-08-03 13:31:23', '2026-08-03 10:01:23', '', 0, 'https://abanenergynova.ir/?p=387', 0, 'customize_changeset', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(372, 1, '2026-08-03 08:56:15', '2026-08-03 05:26:15', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"#\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen4-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --card: #F6F9F7;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen4-about * { box-sizing: border-box; }\n\n  .aen4-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 0.95fr 1.05fr;\n    gap: 3.5rem;\n    align-items: center;\n  }\n\n  .aen4-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen4-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.15rem);\n    line-height: 1.5;\n    color: var(--ink);\n    margin: 0 0 1.1rem;\n  }\n  .aen4-about h2 em { font-style: normal; color: var(--brand); }\n\n  .aen4-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2;\n    color: var(--muted);\n    margin: 0 0 1.1rem;\n  }\n\n  .aen4-stats {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 0.9rem;\n    margin-top: 1.8rem;\n  }\n  .aen4-stat {\n    background: var(--card);\n    border-radius: 14px;\n    padding: 1.1rem 0.9rem;\n    text-align: center;\n  }\n  .aen4-stat b { display: block; font-size: 1.3rem; font-weight: 800; color: var(--ink); margin-bottom: 0.25rem; }\n  .aen4-stat span { font-size: 0.78rem; color: var(--muted); }\n\n  /* --- signature element: نمودار پلتفرم مرکزی متصل به شارژرهای مختلف --- */\n  .aen4-visual {\n    position: relative;\n    aspect-ratio: 1 / 1;\n    max-width: 440px;\n    margin: 0 auto;\n  }\n  .aen4-visual svg { width: 100%; height: 100%; }\n\n  .aen4-node-line {\n    stroke: var(--line);\n    stroke-width: 2;\n    fill: none;\n  }\n  .aen4-node-line--active {\n    stroke: var(--brand);\n    stroke-dasharray: 6 8;\n    animation: aen4Dash 3s linear infinite;\n  }\n  @keyframes aen4Dash { to { stroke-dashoffset: -140; } }\n\n  .aen4-hub-ring { fill: none; stroke: var(--brand-soft); stroke-width: 14; }\n  .aen4-hub { fill: var(--brand); }\n  .aen4-hub-pulse {\n    fill: none; stroke: var(--brand); stroke-width: 2; opacity: 0;\n    animation: aen4Pulse 2.6s ease-out infinite;\n  }\n  @keyframes aen4Pulse {\n    0% { r: 34; opacity: 0.55; }\n    100% { r: 70; opacity: 0; }\n  }\n\n  .aen4-node-card {\n    fill: #FFFFFF;\n    stroke: var(--line);\n    stroke-width: 1.5;\n  }\n  .aen4-node-label {\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    font-size: 11px;\n    fill: var(--ink);\n    font-weight: 700;\n  }\n\n  @media (max-width: 900px) {\n    .aen4-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen4-stats { grid-template-columns: repeat(3, 1fr); }\n    .aen4-visual { order: -1; margin-bottom: 1rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen4-about\">\n  <div class=\"aen4-grid\">\n\n    <div class=\"aen4-text\">\n      <span class=\"aen4-badge\">درباره آبان انرژی نوا</span>\n      <h2>یک شرکت، دو چیزی که با هم <em>معنا پیدا می‌کنند</em></h2>\n      <p>\n        آبان انرژی نوا از سال ۱۴۰۴ فعالیت خود را با تولید، واردات و نصب شارژرهای\n        خودروی برقی آغاز کرد. اما خیلی زود متوجه شدیم صِرف فروش دستگاه کافی نیست؛\n        صاحبان شارژر به یک سیستم برای مدیریت، مانیتورینگ و دریافت هزینه نیاز دارند.\n      </p>\n      <p>\n        به همین دلیل، در کنار تولید شارژر، پلتفرم نرم‌افزاری خودمان را ساختیم —\n        سیستمی که هم روی شارژرهای آبان و هم روی شارژرهای سایر برندها (با پشتیبانی\n        از استاندارد OCPP) قابل نصب است.\n      </p>\n\n      <div class=\"aen4-stats\">\n        <div class=\"aen4-stat\"><b>۱۴۰۴</b><span>سال تأسیس</span></div>\n        <div class=\"aen4-stat\"><b>سخت‌افزار</b><span>+ نرم‌افزار</span></div>\n        <div class=\"aen4-stat\"><b>OCPP</b><span>سازگار با هر برند</span></div>\n      </div>\n    </div>\n\n    <div class=\"aen4-visual\">\n      <svg viewBox=\"0 0 400 400\" xmlns=\"http://www.w3.org/2000/svg\">\n        <!-- خطوط اتصال -->\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 90 90\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 310 90\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 90 310\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 310 310\"/>\n        <path class=\"aen4-node-line\" d=\"M200 200 L 200 60\"/>\n        <path class=\"aen4-node-line\" d=\"M200 200 L 200 340\"/>\n\n        <!-- هاب مرکزی (پلتفرم) -->\n        <circle class=\"aen4-hub-ring\" cx=\"200\" cy=\"200\" r=\"46\"/>\n        <circle class=\"aen4-hub-pulse\" cx=\"200\" cy=\"200\" r=\"34\"/>\n        <circle class=\"aen4-hub\" cx=\"200\" cy=\"200\" r=\"30\"/>\n        <text x=\"200\" y=\"205\" text-anchor=\"middle\" class=\"aen4-node-label\" fill=\"#fff\" font-size=\"12\">آبان</text>\n\n        <!-- نودهای شارژر -->\n        <g>\n          <rect class=\"aen4-node-card\" x=\"60\" y=\"60\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"90\" y=\"88\" text-anchor=\"middle\" class=\"aen4-node-label\">شارژر آبان</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"280\" y=\"60\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"310\" y=\"88\" text-anchor=\"middle\" class=\"aen4-node-label\">برند دیگر</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"60\" y=\"284\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"90\" y=\"312\" text-anchor=\"middle\" class=\"aen4-node-label\">پارکینگ</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"280\" y=\"284\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"310\" y=\"312\" text-anchor=\"middle\" class=\"aen4-node-label\">مجتمع</text>\n        </g>\n      </svg>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"className\":\"col-md-5\"} -->\n<div class=\"wp-block-column col-md-5\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-right\">در مورد آبان انرژی نوا</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\">شرکت آبان انرژی نوادر سال 1404 برای واردات، تولید و نصب شارژهای خودروی برقی با بالاترین کیفیت تاسیس شد</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"col-md-6 col-md-offset1\"} -->\n<div class=\"wp-block-column col-md-6 col-md-offset1\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://abanenergynova.ir/wp-content/uploads/2025/12/eco-friendly-solar-panel-charging-station-for-electric-vehicles-outdoors.-9800036-1536x2048-1-768x1024.jpg\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 08:56:15', '2026-08-03 05:26:15', '', 15, 'https://abanenergynova.ir/?p=372', 0, 'revision', '', 0),
(375, 1, '2026-08-03 10:42:46', '2026-08-03 07:12:46', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"#\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 10:42:46', '2026-08-03 07:12:46', '', 15, 'https://abanenergynova.ir/?p=375', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(374, 1, '2026-08-03 10:42:29', '2026-08-03 07:12:29', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"#\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"className\":\"col-md-5\"} -->\n<div class=\"wp-block-column col-md-5\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-right\">در مورد آبان انرژی نوا</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\">شرکت آبان انرژی نوادر سال 1404 برای واردات، تولید و نصب شارژهای خودروی برقی با بالاترین کیفیت تاسیس شد</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"col-md-6 col-md-offset1\"} -->\n<div class=\"wp-block-column col-md-6 col-md-offset1\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://abanenergynova.ir/wp-content/uploads/2025/12/eco-friendly-solar-panel-charging-station-for-electric-vehicles-outdoors.-9800036-1536x2048-1-768x1024.jpg\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 10:42:29', '2026-08-03 07:12:29', '', 15, 'https://abanenergynova.ir/?p=374', 0, 'revision', '', 0),
(373, 1, '2026-08-03 08:57:30', '2026-08-03 05:27:30', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"#\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen4-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --card: #F6F9F7;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen4-about * { box-sizing: border-box; }\n\n  .aen4-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 0.95fr 1.05fr;\n    gap: 3.5rem;\n    align-items: center;\n  }\n\n  .aen4-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen4-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.15rem);\n    line-height: 1.5;\n    color: var(--ink);\n    margin: 0 0 1.1rem;\n  }\n  .aen4-about h2 em { font-style: normal; color: var(--brand); }\n\n  .aen4-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2;\n    color: var(--muted);\n    margin: 0 0 1.1rem;\n  }\n\n  .aen4-stats {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 0.9rem;\n    margin-top: 1.8rem;\n  }\n  .aen4-stat {\n    background: var(--card);\n    border-radius: 14px;\n    padding: 1.1rem 0.9rem;\n    text-align: center;\n  }\n  .aen4-stat b { display: block; font-size: 1.3rem; font-weight: 800; color: var(--ink); margin-bottom: 0.25rem; }\n  .aen4-stat span { font-size: 0.78rem; color: var(--muted); }\n\n  /* --- signature element: نمودار پلتفرم مرکزی متصل به شارژرهای مختلف --- */\n  .aen4-visual {\n    position: relative;\n    aspect-ratio: 1 / 1;\n    max-width: 440px;\n    margin: 0 auto;\n  }\n  .aen4-visual svg { width: 100%; height: 100%; }\n\n  .aen4-node-line {\n    stroke: var(--line);\n    stroke-width: 2;\n    fill: none;\n  }\n  .aen4-node-line--active {\n    stroke: var(--brand);\n    stroke-dasharray: 6 8;\n    animation: aen4Dash 3s linear infinite;\n  }\n  @keyframes aen4Dash { to { stroke-dashoffset: -140; } }\n\n  .aen4-hub-ring { fill: none; stroke: var(--brand-soft); stroke-width: 14; }\n  .aen4-hub { fill: var(--brand); }\n  .aen4-hub-pulse {\n    fill: none; stroke: var(--brand); stroke-width: 2; opacity: 0;\n    animation: aen4Pulse 2.6s ease-out infinite;\n  }\n  @keyframes aen4Pulse {\n    0% { r: 34; opacity: 0.55; }\n    100% { r: 70; opacity: 0; }\n  }\n\n  .aen4-node-card {\n    fill: #FFFFFF;\n    stroke: var(--line);\n    stroke-width: 1.5;\n  }\n  .aen4-node-label {\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    font-size: 11px;\n    fill: var(--ink);\n    font-weight: 700;\n  }\n\n  @media (max-width: 900px) {\n    .aen4-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen4-stats { grid-template-columns: repeat(3, 1fr); }\n    .aen4-visual { order: -1; margin-bottom: 1rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen4-about\">\n  <div class=\"aen4-grid\">\n\n    <div class=\"aen4-text\">\n      <span class=\"aen4-badge\">درباره آبان انرژی نوا</span>\n      <h2>یک شرکت، دو چیزی که با هم <em>معنا پیدا می‌کنند</em></h2>\n      <p>\n        آبان انرژی نوا از سال ۱۴۰۴ فعالیت خود را با تولید، واردات و نصب شارژرهای\n        خودروی برقی آغاز کرد. اما خیلی زود متوجه شدیم صِرف فروش دستگاه کافی نیست؛\n        صاحبان شارژر به یک سیستم برای مدیریت، مانیتورینگ و دریافت هزینه نیاز دارند.\n      </p>\n      <p>\n        به همین دلیل، در کنار تولید شارژر، پلتفرم نرم‌افزاری خودمان را ساختیم —\n        سیستمی که هم روی شارژرهای آبان و هم روی شارژرهای سایر برندها (با پشتیبانی\n        از استاندارد OCPP) قابل نصب است.\n      </p>\n\n      <div class=\"aen4-stats\">\n        <div class=\"aen4-stat\"><b>۱۴۰۴</b><span>سال تأسیس</span></div>\n        <div class=\"aen4-stat\"><b>سخت‌افزار</b><span>+ نرم‌افزار</span></div>\n        <div class=\"aen4-stat\"><b>OCPP</b><span>سازگار با هر برند</span></div>\n      </div>\n    </div>\n\n    <div class=\"aen4-visual\">\n      <svg viewBox=\"0 0 400 400\" xmlns=\"http://www.w3.org/2000/svg\">\n        <!-- خطوط اتصال -->\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 90 90\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 310 90\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 90 310\"/>\n        <path class=\"aen4-node-line aen4-node-line--active\" d=\"M200 200 L 310 310\"/>\n        <path class=\"aen4-node-line\" d=\"M200 200 L 200 60\"/>\n        <path class=\"aen4-node-line\" d=\"M200 200 L 200 340\"/>\n\n        <!-- هاب مرکزی (پلتفرم) -->\n        <circle class=\"aen4-hub-ring\" cx=\"200\" cy=\"200\" r=\"46\"/>\n        <circle class=\"aen4-hub-pulse\" cx=\"200\" cy=\"200\" r=\"34\"/>\n        <circle class=\"aen4-hub\" cx=\"200\" cy=\"200\" r=\"30\"/>\n        <text x=\"200\" y=\"205\" text-anchor=\"middle\" class=\"aen4-node-label\" fill=\"#fff\" font-size=\"12\">آبان</text>\n\n        <!-- نودهای شارژر -->\n        <g>\n          <rect class=\"aen4-node-card\" x=\"60\" y=\"60\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"90\" y=\"88\" text-anchor=\"middle\" class=\"aen4-node-label\">شارژر آبان</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"280\" y=\"60\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"310\" y=\"88\" text-anchor=\"middle\" class=\"aen4-node-label\">برند دیگر</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"60\" y=\"284\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"90\" y=\"312\" text-anchor=\"middle\" class=\"aen4-node-label\">پارکینگ</text>\n        </g>\n        <g>\n          <rect class=\"aen4-node-card\" x=\"280\" y=\"284\" width=\"60\" height=\"46\" rx=\"10\"/>\n          <text x=\"310\" y=\"312\" text-anchor=\"middle\" class=\"aen4-node-label\">مجتمع</text>\n        </g>\n      </svg>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"className\":\"col-md-5\"} -->\n<div class=\"wp-block-column col-md-5\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-right\">در مورد آبان انرژی نوا</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\">شرکت آبان انرژی نوادر سال 1404 برای واردات، تولید و نصب شارژهای خودروی برقی با بالاترین کیفیت تاسیس شد</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"col-md-6 col-md-offset1\"} -->\n<div class=\"wp-block-column col-md-6 col-md-offset1\"><!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":42,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://abanenergynova.ir/wp-content/uploads/2025/12/eco-friendly-solar-panel-charging-station-for-electric-vehicles-outdoors.-9800036-1536x2048-1-768x1024.jpg\" alt=\"\" class=\"wp-image-42\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 08:57:30', '2026-08-03 05:27:30', '', 15, 'https://abanenergynova.ir/?p=373', 0, 'revision', '', 0),
(390, 1, '2026-08-03 13:43:40', '2026-08-03 10:13:40', '<label> Your name\n    [text* your-name autocomplete:name] </label>\n\n<label> Your email\n    [email* your-email autocomplete:email] </label>\n\n<label> Subject\n    [text* your-subject] </label>\n\n<label> Your message (optional)\n    [textarea your-message] </label>\n\n[submit \"Submit\"]\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@abanenergynova.ir>\nFrom: [your-name] [your-email]\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\n[_site_admin_email]\nReply-To: [your-email]\n\n0\n0\n\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@abanenergynova.ir>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.', 'Contact form 1', '', 'publish', 'closed', 'closed', '', 'contact-form-1', '', '', '2026-08-03 13:43:40', '2026-08-03 10:13:40', '', 0, 'https://abanenergynova.ir/?post_type=wpcf7_contact_form&p=390', 0, 'wpcf7_contact_form', '', 0),
(391, 1, '2026-08-03 14:01:56', '2026-08-03 10:31:56', '<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"className\":\"hestia-title\"} -->\n<h2 class=\"wp-block-heading hestia-title\">Send us a message</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<div class=\"contact-wrapper\">\n																			<div class=\"content\">\n			\n			  <form>\n			   <div class=\"form-group\">\n			    <input type=\"text\" id=\"fname\" name=\"firstname\" placeholder=\"Your name..\">\n			</div>\n			<div class=\"form-group\">\n			    <input type=\"text\" id=\"lname\" name=\"lastname\" placeholder=\"Your last name..\">\n			</div>\n			<div class=\"form-group\">\n			    <textarea id=\"subject\" name=\"subject\" placeholder=\"Write something..\" style=\"height:200px\"></textarea>\n			</div>\n			    <input type=\"submit\" value=\"Submit\">\n			\n			  </form>\n			</div>\n			</div>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"metadata\":{\"blockVisibility\":false}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":4,\"className\":\"hestia-title\",\"style\":{\"typography\":{\"fontSize\":18,\"textAlign\":\"right\"},\"color\":{\"text\":\"#3c4858\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-right hestia-title has-text-color\" style=\"color:#3c4858;font-size:18px\"><img class=\"wp-image-86\" style=\"width: 25px;\" src=\"http://abanenergynova.ir/wp-content/themes/hestia/assets/img/contact1.png\" alt=\"Map icon\"> آدرس  </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-text-color\",\"style\":{\"typography\":{\"fontSize\":14,\"textAlign\":\"right\"},\"color\":{\"text\":\"#999999\"}}} -->\n<p class=\"has-text-align-right has-text-color\" style=\"color:#999999;font-size:14px\">مهرآباد جنوبی، خیابان کوسه لو، تهران <br>ایران</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"hestia-title\",\"style\":{\"typography\":{\"fontSize\":18,\"textAlign\":\"right\"},\"color\":{\"text\":\"#3c4858\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-right hestia-title has-text-color\" style=\"color:#3c4858;font-size:18px\"><img class=\"wp-image-98\" style=\"width: 25px;\" src=\"http://abanenergynova.ir/wp-content/themes/hestia/assets/img/contact2.png\" alt=\"\"> تماس با ما</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-text-color\",\"style\":{\"color\":{\"text\":\"#999999\"},\"typography\":{\"fontSize\":14,\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right has-text-color\" style=\"color:#999999;font-size:14px\">اسدیان<br>+98 919999999<br>Mon - Fri, 8:00-22:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'تماس با ما', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-08-03 14:01:56', '2026-08-03 10:31:56', '', 16, 'https://abanenergynova.ir/?p=391', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(392, 1, '2026-08-03 14:04:49', '2026-08-03 10:34:49', '<!-- wp:paragraph -->\n<p>این یک برگهٔ نمونه است. این از یک نوشتهٔ وبلاگ متفاوت است زیرا در یک مکان باقی خواهد ماند و در راهبری سایتتان (در بیشتر پوسته‌ها) نشان داده خواهد شد. بیشتر مردم با یک برگه درباره که آن‌ها را به بازدیدکنندگان بالقوهٔ سایت معرفی می‌کند، آغاز می‌کنند. که ممکن است چیزی همانند این باشد:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>سلام! من یک پیام‌رسان دوچرخه‌سوار در روز، بازیگر مشتاق در شب هستم، و این وب‌سایت من است. من در لس آنجلس زندگی می‌کنم، یک سگ بزرگ به نام جک دارم، و من پینیا کولادا دوست دارم. (همچنین گرفتار شدن در باران را دوست دارم.)</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...یا چیزهایی مانند این:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>شرکت XYZ در سال ۱۹۷۱ تأسیس شد، و تا کنون چیزهای با کیفیتی را به عموم عرضه کرده است. این شرکت در شهر گاتهام واقع شده است، بیش از ۲۰۰۰ نفر در آن کار می‌کنند و همه نوع چیز عالی برای جامعه گاتهام انجام می‌دهد.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>به عنوان یک کاربر جدید وردپرس، برای حذف این برگه و ایجاد برگه‌های جدید برای محتوای خود شما باید به <a href=\"http://abanenergynova.ir/wp-admin/\">پیشخوان</a> بروید. خوش بگذره!</p>\n<!-- /wp:paragraph -->', 'شروع شارژ', '', 'inherit', 'closed', 'closed', '', '2-revision-v1', '', '', '2026-08-03 14:04:49', '2026-08-03 10:34:49', '', 2, 'https://abanenergynova.ir/?p=392', 0, 'revision', '', 0),
(398, 1, '2026-08-03 14:46:59', '2026-08-03 11:16:59', '<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"className\":\"hestia-title\"} -->\n<h2 class=\"wp-block-heading hestia-title\">Send us a message</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<div class=\"contact-wrapper\">\n																			<div class=\"content\">\n			\n			  <form>\n			   <div class=\"form-group\">\n			    <input type=\"text\" id=\"fname\" name=\"firstname\" placeholder=\"Your name..\">\n			</div>\n			<div class=\"form-group\">\n			    <input type=\"text\" id=\"lname\" name=\"lastname\" placeholder=\"Your last name..\">\n			</div>\n			<div class=\"form-group\">\n			    <textarea id=\"subject\" name=\"subject\" placeholder=\"Write something..\" style=\"height:200px\"></textarea>\n			</div>\n			    <input type=\"submit\" value=\"Submit\">\n			\n			  </form>\n			</div>\n			</div>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"metadata\":{\"blockVisibility\":false}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":4,\"className\":\"hestia-title\",\"style\":{\"typography\":{\"fontSize\":18,\"textAlign\":\"right\"},\"color\":{\"text\":\"#3c4858\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-right hestia-title has-text-color\" style=\"color:#3c4858;font-size:18px\"><img class=\"wp-image-86\" style=\"width: 25px;\" src=\"http://abanenergynova.ir/wp-content/themes/hestia/assets/img/contact1.png\" alt=\"Map icon\"> آدرس  </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-text-color\",\"style\":{\"typography\":{\"fontSize\":14,\"textAlign\":\"right\"},\"color\":{\"text\":\"#999999\"}}} -->\n<p class=\"has-text-align-right has-text-color\" style=\"color:#999999;font-size:14px\">مهرآباد جنوبی، خیابان کوسه لو، تهران <br>ایران</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":4,\"className\":\"hestia-title\",\"style\":{\"typography\":{\"fontSize\":18,\"textAlign\":\"right\"},\"color\":{\"text\":\"#3c4858\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-right hestia-title has-text-color\" style=\"color:#3c4858;font-size:18px\"><img class=\"wp-image-98\" style=\"width: 25px;\" src=\"http://abanenergynova.ir/wp-content/themes/hestia/assets/img/contact2.png\" alt=\"\"> تماس با ما</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-text-color\",\"style\":{\"color\":{\"text\":\"#999999\"},\"typography\":{\"fontSize\":14,\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right has-text-color\" style=\"color:#999999;font-size:14px\">اسدیان<br>+98 919999999<br>Mon - Fri, 8:00-22:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'تماس با ما', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-08-03 14:46:59', '2026-08-03 11:16:59', '', 16, 'https://abanenergynova.ir/?p=398', 0, 'revision', '', 0),
(394, 1, '2026-08-03 14:06:27', '2026-08-03 10:36:27', '<!-- wp:html -->\n<!-- ===================================================================\n     صفحه \"شروع شارژ\" — راهنمای مراحل استفاده — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ (تو یه صفحه جدید به اسم \"شروع شارژ\")\n     پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen7-guide {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --card: #F6F9F7;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    box-sizing: border-box;\n  }\n  .aen7-guide * { box-sizing: border-box; }\n\n  /* --- هدر صفحه --- */\n  .aen7-hero {\n    background: radial-gradient(120% 160% at 20% 0%, #0F2A1E 0%, #0B1F17 60%);\n    color: #F4F7F5;\n    padding: 4.5vw 6vw;\n    text-align: center;\n  }\n  .aen7-hero span.aen7-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: #4CD787;\n    background: rgba(76,215,135,0.1);\n    border: 1px solid rgba(76,215,135,0.25);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.1rem;\n  }\n  .aen7-hero h1 {\n    font-weight: 800;\n    font-size: clamp(1.8rem, 3.2vw, 2.6rem);\n    margin: 0 0 0.9rem;\n  }\n  .aen7-hero p {\n    font-size: 1rem;\n    line-height: 2;\n    color: #9FB3A8;\n    max-width: 38rem;\n    margin: 0 auto;\n  }\n\n  /* --- مراحل --- */\n  .aen7-steps {\n    max-width: 1080px;\n    margin: 0 auto;\n    padding: 5vw 6vw;\n  }\n\n  .aen7-steps-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.2rem;\n    position: relative;\n  }\n\n  .aen7-step {\n    position: relative;\n    background: var(--card);\n    border-radius: 16px;\n    padding: 1.8rem 1.4rem;\n    text-align: center;\n  }\n\n  .aen7-step-num {\n    width: 42px;\n    height: 42px;\n    margin: 0 auto 1.1rem;\n    border-radius: 50%;\n    background: var(--brand);\n    color: #fff;\n    font-weight: 800;\n    font-size: 1.05rem;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .aen7-step h3 {\n    font-size: 1rem;\n    font-weight: 700;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-step p {\n    font-size: 0.88rem;\n    line-height: 1.85;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  .aen7-arrow {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--line);\n  }\n\n  /* --- بنر پایانی: به‌زودی --- */\n  .aen7-soon {\n    max-width: 1080px;\n    margin: 0 auto 5vw;\n    padding: 0 6vw;\n  }\n  .aen7-soon-box {\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.2);\n    border-radius: 18px;\n    padding: 2.2rem 2rem;\n    text-align: center;\n  }\n  .aen7-soon-box h2 {\n    font-size: 1.2rem;\n    font-weight: 800;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-soon-box p {\n    font-size: 0.95rem;\n    color: var(--muted);\n    line-height: 1.9;\n    max-width: 32rem;\n    margin: 0 auto 1.4rem;\n  }\n  .aen7-soon-box a {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    background: var(--brand);\n    color: #fff;\n    text-decoration: none;\n    font-weight: 700;\n    font-size: 0.94rem;\n    padding: 0.85rem 1.8rem;\n    border-radius: 10px;\n    transition: background .15s ease, transform .15s ease;\n  }\n  .aen7-soon-box a:hover { background: var(--brand-deep); transform: translateY(-2px); }\n\n  @media (max-width: 900px) {\n    .aen7-steps-grid { grid-template-columns: 1fr 1fr; }\n    .aen7-arrow { display: none; }\n  }\n  @media (max-width: 560px) {\n    .aen7-steps-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<div class=\"aen7-guide\">\n\n  <section class=\"aen7-hero\">\n    <span class=\"aen7-badge\">راهنمای شارژ</span>\n    <h1>شارژ کردن با آبان، در ۴ قدم ساده</h1>\n    <p>\n      وقتی پلتفرم آبان روی ایستگاه شارژ شما فعال باشد، رساندن خودرو به شارژ کامل\n      دیگر نیازی به کارت یا اپراتور جداگانه ندارد.\n    </p>\n  </section>\n\n  <section class=\"aen7-steps\">\n    <div class=\"aen7-steps-grid\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۱</div>\n        <h3>پیدا کردن ایستگاه</h3>\n        <p>نزدیک‌ترین ایستگاه فعال آبان را از روی نقشه یا لیست ایستگاه‌ها پیدا کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۲</div>\n        <h3>انتخاب دستگاه</h3>\n        <p>کد دستگاه را اسکن یا از لیست انتخاب کنید تا وضعیت آن را ببینید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n\n    <div class=\"aen7-steps-grid\" style=\"margin-top: 1.2rem;\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۳</div>\n        <h3>اتصال کابل</h3>\n        <p>کابل شارژ را به خودروی خود وصل کنید و شارژ را از داشبورد شروع کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۴</div>\n        <h3>پرداخت از کیف پول</h3>\n        <p>هزینه شارژ خودکار از کیف پول کسر می‌شود؛ رسید هم همان لحظه صادر می‌شود.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"opacity:0\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n  </section>\n\n  <section class=\"aen7-soon\">\n    <div class=\"aen7-soon-box\">\n      <h2>پلتفرم شارژ آبان به‌زودی راه‌اندازی می‌شود</h2>\n      <p>\n        در حال حاضر در حال راه‌اندازی زیرساخت نرم‌افزاری هستیم. برای اطلاع از زمان\n        فعال‌سازی ایستگاه‌ها یا هماهنگی نصب شارژر، با ما در تماس باشید.\n      </p>\n      <a href=\"/contact/\">تماس با ما ←</a>\n    </div>\n  </section>\n\n</div>\n<!-- /wp:html -->', 'شروع شارژ', '', 'inherit', 'closed', 'closed', '', '2-revision-v1', '', '', '2026-08-03 14:06:27', '2026-08-03 10:36:27', '', 2, 'https://abanenergynova.ir/?p=394', 0, 'revision', '', 0),
(395, 1, '2026-08-03 14:22:12', '2026-08-03 10:52:12', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual { order: -1; height: 340px; margin: 0 auto 1rem; max-width: 340px; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"/start-charging/\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 14:22:12', '2026-08-03 10:52:12', '', 15, 'https://abanenergynova.ir/?p=395', 0, 'revision', '', 0),
(396, 1, '2026-08-03 14:23:38', '2026-08-03 10:53:38', '{\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- ===================================================================\\n     \\u0641\\u0648\\u062a\\u0631 \\u2014 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627\\n     \\u0646\\u062d\\u0648\\u0647 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647: \\u06a9\\u0644 \\u0627\\u06cc\\u0646 \\u06a9\\u062f \\u0631\\u0648 \\u062f\\u0627\\u062e\\u0644 \\u06cc\\u06a9 \\u0648\\u06cc\\u062c\\u062a \\\"HTML\\\" \\u062f\\u0631 Elementor \\u06cc\\u0627\\n     \\u0628\\u0644\\u0627\\u06a9 \\\"Custom HTML\\\" \\u062f\\u0631 \\u06af\\u0648\\u062a\\u0646\\u0628\\u0631\\u06af \\u067e\\u06cc\\u0633\\u062a \\u06a9\\u0646 (\\u067e\\u0627\\u06cc\\u06cc\\u0646\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0628\\u0644\\u0627\\u06a9 \\u0635\\u0641\\u062d\\u0647).\\n     \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b self-contained \\u0627\\u0633\\u062a.\\n==================================================================== -->\\n\\n<style>\\n  .aen6-footer {\\n    --ink: #0F2A1E;\\n    --muted: #9FB3A8;\\n    --line: rgba(244,247,245,0.12);\\n    --bg: #0B1F17;\\n    --brand: #159A5B;\\n    --brand-bright: #4CD787;\\n    --off: #F4F7F5;\\n\\n    direction: rtl;\\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\\n    background: var(--bg);\\n    color: var(--off);\\n    padding: 4vw 6vw 2vw;\\n    box-sizing: border-box;\\n  }\\n  .aen6-footer * { box-sizing: border-box; }\\n\\n  .aen6-top {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    display: grid;\\n    grid-template-columns: 1.2fr 0.8fr 1fr 1fr;\\n    gap: 2.4rem;\\n    padding-bottom: 2.6rem;\\n  }\\n\\n  .aen6-brand-name {\\n    font-weight: 800;\\n    font-size: 1.15rem;\\n    color: var(--off);\\n    margin: 0 0 0.9rem;\\n  }\\n  .aen6-brand-name span { color: var(--brand-bright); }\\n\\n  .aen6-top p.aen6-desc {\\n    font-size: 0.9rem;\\n    line-height: 1.9;\\n    color: var(--muted);\\n    margin: 0;\\n    max-width: 22rem;\\n  }\\n\\n  .aen6-col h4 {\\n    font-size: 0.92rem;\\n    font-weight: 700;\\n    color: var(--off);\\n    margin: 0 0 1.1rem;\\n  }\\n\\n  .aen6-col ul {\\n    list-style: none;\\n    margin: 0;\\n    padding: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.75rem;\\n  }\\n  .aen6-col a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    font-size: 0.88rem;\\n    transition: color .15s ease;\\n  }\\n  .aen6-col a:hover { color: var(--brand-bright); }\\n\\n  .aen6-col .aen6-cta a {\\n    color: var(--brand-bright);\\n    font-weight: 700;\\n  }\\n\\n  .aen6-contact li {\\n    font-size: 0.88rem;\\n    color: var(--muted);\\n    line-height: 1.85;\\n  }\\n  .aen6-contact li b {\\n    display: block;\\n    color: var(--off);\\n    font-weight: 700;\\n    font-size: 0.85rem;\\n    margin-bottom: 0.15rem;\\n  }\\n  .aen6-contact li a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    direction: ltr;\\n    display: inline-block;\\n  }\\n  .aen6-contact li a:hover { color: var(--brand-bright); }\\n\\n  .aen6-bottom {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    border-top: 1px solid var(--line);\\n    padding-top: 1.4rem;\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    flex-wrap: wrap;\\n    gap: 0.8rem;\\n    font-size: 0.8rem;\\n    color: var(--muted);\\n  }\\n\\n  @media (max-width: 900px) {\\n    .aen6-top { grid-template-columns: 1fr 1fr; }\\n  }\\n  @media (max-width: 560px) {\\n    .aen6-top { grid-template-columns: 1fr; text-align: center; }\\n    .aen6-top p.aen6-desc { max-width: 100%; margin: 0 auto; }\\n    .aen6-col ul { align-items: center; }\\n    .aen6-bottom { justify-content: center; text-align: center; }\\n  }\\n</style>\\n\\n<link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\">\\n<link href=\\\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\\\" rel=\\\"stylesheet\\\">\\n\\n<footer class=\\\"aen6-footer\\\">\\n  <div class=\\\"aen6-top\\\">\\n\\n    <div class=\\\"aen6-brand\\\">\\n      <div class=\\\"aen6-brand-name\\\">\\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc <span>\\u0646\\u0648\\u0627</span></div>\\n      <p class=\\\"aen6-desc\\\">\\n        \\u062a\\u0648\\u0644\\u06cc\\u062f\\u060c \\u0648\\u0627\\u0631\\u062f\\u0627\\u062a \\u0648 \\u0646\\u0635\\u0628 \\u0634\\u0627\\u0631\\u0698\\u0631\\u0647\\u0627\\u06cc \\u062e\\u0648\\u062f\\u0631\\u0648\\u06cc \\u0628\\u0631\\u0642\\u06cc\\u060c \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645 \\u0646\\u0631\\u0645\\u200c\\u0627\\u0641\\u0632\\u0627\\u0631\\u06cc\\n        \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0634\\u0627\\u0631\\u0698 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0628\\u0627 \\u0627\\u0633\\u062a\\u0627\\u0646\\u062f\\u0627\\u0631\\u062f OCPP.\\n      </p>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u0633\\u0631\\u06cc\\u0639</h4>\\n      <ul>\\n        <li><a href=\\\"/\\\">\\u062e\\u0627\\u0646\\u0647</a></li>\\n        <li class=\\\"aen6-cta\\\"><a href=\\\"/start-charging/\\\">\\u0634\\u0631\\u0648\\u0639 \\u0634\\u0627\\u0631\\u0698\\u0631</a></li>\\n        <li><a href=\\\"#\\\">\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0634\\u0627\\u0631\\u0698\\u0631 \\u0634\\u0645\\u0627</a></li>\\n        <li><a href=\\\"/contact/\\\">\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</a></li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u062a\\u0644\\u0641\\u0646</b>\\n          <a href=\\\"tel:+982166649792\\\">021 66649792</a>\\n        </li>\\n        <li>\\n          <b>\\u0641\\u0631\\u0648\\u0634</b>\\n          <a href=\\\"tel:+989193341696\\\">0919 334 1696</a>\\n        </li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u0622\\u062f\\u0631\\u0633 \\u0648 \\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u0622\\u062f\\u0631\\u0633</b>\\n          \\u0645\\u0647\\u0631\\u0622\\u0628\\u0627\\u062f \\u062c\\u0646\\u0648\\u0628\\u06cc\\u060c \\u062e\\u06cc\\u0627\\u0628\\u0627\\u0646 \\u06a9\\u0648\\u0633\\u0647\\u200c\\u0644\\u0648\\u060c \\u062a\\u0647\\u0631\\u0627\\u0646\\u060c \\u0627\\u06cc\\u0631\\u0627\\u0646\\n        </li>\\n        <li>\\n          <b>\\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</b>\\n          \\u0634\\u0646\\u0628\\u0647 \\u062a\\u0627 \\u0686\\u0647\\u0627\\u0631\\u0634\\u0646\\u0628\\u0647\\u060c \\u06f8 \\u062a\\u0627 \\u06f1\\u06f6\\n        </li>\\n      </ul>\\n    </div>\\n\\n  </div>\\n\\n  <div class=\\\"aen6-bottom\\\">\\n    <span>\\u00a9 \\u06f1\\u06f4\\u06f0\\u06f4 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627. \\u062a\\u0645\\u0627\\u0645\\u06cc \\u062d\\u0642\\u0648\\u0642 \\u0645\\u062d\\u0641\\u0648\\u0638 \\u0627\\u0633\\u062a.</span>\\n    <span>\\u0633\\u0627\\u062e\\u062a\\u0647\\u200c\\u0634\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647\\u200c\\u06cc \\u0634\\u0627\\u0631\\u0698 \\u0647\\u0648\\u0634\\u0645\\u0646\\u062f</span>\\n  </div>\\n</footer>\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 10:53:38\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '7e74f745-4f98-4a9c-aeac-a755cb9dab83', '', '', '2026-08-03 14:23:38', '2026-08-03 10:53:38', '', 0, 'https://abanenergynova.ir/2026/08/03/7e74f745-4f98-4a9c-aeac-a755cb9dab83/', 0, 'customize_changeset', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(397, 1, '2026-08-03 14:26:04', '2026-08-03 10:56:04', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual {\n      order: -1;\n      position: static;\n      height: auto;\n      max-width: 320px;\n      margin: 0 auto 1.6rem;\n      display: flex;\n      flex-direction: column;\n      gap: 1rem;\n    }\n    .aen2-card {\n      position: static;\n      width: 100% !important;\n      max-width: 100% !important;\n    }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"/start-charging/\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 14:26:04', '2026-08-03 10:56:04', '', 15, 'https://abanenergynova.ir/?p=397', 0, 'revision', '', 0),
(399, 1, '2026-08-03 14:47:10', '2026-08-03 11:17:10', '<!-- wp:html -->\n<!-- ===================================================================\n     صفحه \"شروع شارژ\" — راهنمای مراحل استفاده — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ (تو یه صفحه جدید به اسم \"شروع شارژ\")\n     پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen7-guide {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --card: #F6F9F7;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    box-sizing: border-box;\n  }\n  .aen7-guide * { box-sizing: border-box; }\n\n  /* --- هدر صفحه --- */\n  .aen7-hero {\n    background: radial-gradient(120% 160% at 20% 0%, #0F2A1E 0%, #0B1F17 60%);\n    color: #F4F7F5;\n    padding: 4.5vw 6vw;\n    text-align: center;\n  }\n  .aen7-hero span.aen7-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: #4CD787;\n    background: rgba(76,215,135,0.1);\n    border: 1px solid rgba(76,215,135,0.25);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.1rem;\n  }\n  .aen7-hero h1 {\n    font-weight: 800;\n    font-size: clamp(1.8rem, 3.2vw, 2.6rem);\n    margin: 0 0 0.9rem;\n  }\n  .aen7-hero p {\n    font-size: 1rem;\n    line-height: 2;\n    color: #9FB3A8;\n    max-width: 38rem;\n    margin: 0 auto;\n  }\n\n  /* --- مراحل --- */\n  .aen7-steps {\n    max-width: 1080px;\n    margin: 0 auto;\n    padding: 5vw 6vw;\n  }\n\n  .aen7-steps-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.2rem;\n    position: relative;\n  }\n\n  .aen7-step {\n    position: relative;\n    background: var(--card);\n    border-radius: 16px;\n    padding: 1.8rem 1.4rem;\n    text-align: center;\n  }\n\n  .aen7-step-num {\n    width: 42px;\n    height: 42px;\n    margin: 0 auto 1.1rem;\n    border-radius: 50%;\n    background: var(--brand);\n    color: #fff;\n    font-weight: 800;\n    font-size: 1.05rem;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .aen7-step h3 {\n    font-size: 1rem;\n    font-weight: 700;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-step p {\n    font-size: 0.88rem;\n    line-height: 1.85;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  .aen7-arrow {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--line);\n  }\n\n  /* --- بنر پایانی: به‌زودی --- */\n  .aen7-soon {\n    max-width: 1080px;\n    margin: 0 auto 5vw;\n    padding: 0 6vw;\n  }\n  .aen7-soon-box {\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.2);\n    border-radius: 18px;\n    padding: 2.2rem 2rem;\n    text-align: center;\n  }\n  .aen7-soon-box h2 {\n    font-size: 1.2rem;\n    font-weight: 800;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-soon-box p {\n    font-size: 0.95rem;\n    color: var(--muted);\n    line-height: 1.9;\n    max-width: 32rem;\n    margin: 0 auto 1.4rem;\n  }\n  .aen7-soon-box a {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    background: var(--brand);\n    color: #fff;\n    text-decoration: none;\n    font-weight: 700;\n    font-size: 0.94rem;\n    padding: 0.85rem 1.8rem;\n    border-radius: 10px;\n    transition: background .15s ease, transform .15s ease;\n  }\n  .aen7-soon-box a:hover { background: var(--brand-deep); transform: translateY(-2px); }\n\n  @media (max-width: 900px) {\n    .aen7-steps-grid { grid-template-columns: 1fr 1fr; }\n    .aen7-arrow { display: none; }\n  }\n  @media (max-width: 560px) {\n    .aen7-steps-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<div class=\"aen7-guide\">\n\n  <section class=\"aen7-hero\">\n    <span class=\"aen7-badge\">راهنمای شارژ</span>\n    <h1>شارژ کردن با آبان، در ۴ قدم ساده</h1>\n    <p>\n      وقتی پلتفرم آبان روی ایستگاه شارژ شما فعال باشد، رساندن خودرو به شارژ کامل\n      دیگر نیازی به کارت یا اپراتور جداگانه ندارد.\n    </p>\n  </section>\n\n  <section class=\"aen7-steps\">\n    <div class=\"aen7-steps-grid\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۱</div>\n        <h3>پیدا کردن ایستگاه</h3>\n        <p>نزدیک‌ترین ایستگاه فعال آبان را از روی نقشه یا لیست ایستگاه‌ها پیدا کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۲</div>\n        <h3>انتخاب دستگاه</h3>\n        <p>کد دستگاه را اسکن یا از لیست انتخاب کنید تا وضعیت آن را ببینید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n\n    <div class=\"aen7-steps-grid\" style=\"margin-top: 1.2rem;\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۳</div>\n        <h3>اتصال کابل</h3>\n        <p>کابل شارژ را به خودروی خود وصل کنید و شارژ را از داشبورد شروع کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۴</div>\n        <h3>پرداخت از کیف پول</h3>\n        <p>هزینه شارژ خودکار از کیف پول کسر می‌شود؛ رسید هم همان لحظه صادر می‌شود.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"opacity:0\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n  </section>\n\n  <section class=\"aen7-soon\">\n    <div class=\"aen7-soon-box\">\n      <h2>پلتفرم شارژ آبان به‌زودی راه‌اندازی می‌شود</h2>\n      <p>\n        در حال حاضر در حال راه‌اندازی زیرساخت نرم‌افزاری هستیم. برای اطلاع از زمان\n        فعال‌سازی ایستگاه‌ها یا هماهنگی نصب شارژر، با ما در تماس باشید.\n      </p>\n      <a href=\"/contact/\">تماس با ما ←</a>\n    </div>\n  </section>\n\n</div>\n<!-- /wp:html -->', 'شروع شارژ', '', 'inherit', 'closed', 'closed', '', '2-revision-v1', '', '', '2026-08-03 14:47:10', '2026-08-03 11:17:10', '', 2, 'https://abanenergynova.ir/?p=399', 0, 'revision', '', 0),
(400, 1, '2026-08-03 14:47:30', '2026-08-03 11:17:30', '<!-- wp:html -->\n<!-- ===================================================================\n     بلاک Hero v2 — آبان انرژی نوا (سبک SaaS / پلتفرم نرم‌افزاری)\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen2-hero {\n    --ink: #0F2A1E;         /* متن اصلی، سبز خیلی تیره */\n    --muted: #5B6B63;       /* متن کم‌رنگ */\n    --line: #E3EAE5;        /* خطوط ظریف */\n    --bg: #FAFCFA;          /* پس‌زمینه روشن */\n    --card: #FFFFFF;\n    --brand: #159A5B;       /* سبز برند اصلی */\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;  /* سبز خیلی روشن، پس‌زمینه بج/تگ */\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    color: var(--ink);\n    padding: 5vw 6vw 4vw;\n    box-sizing: border-box;\n  }\n  .aen2-hero * { box-sizing: border-box; }\n\n  .aen2-grid {\n    display: grid;\n    grid-template-columns: 1.05fr 0.95fr;\n    gap: 3.5rem;\n    align-items: center;\n    max-width: 1180px;\n    margin: 0 auto;\n  }\n\n  .aen2-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.18);\n    padding: 0.45rem 0.95rem;\n    border-radius: 999px;\n    margin-bottom: 1.4rem;\n  }\n\n  .aen2-hero h1 {\n    font-weight: 800;\n    font-size: clamp(2rem, 3.6vw, 3.1rem);\n    line-height: 1.35;\n    margin: 0 0 1.1rem;\n    color: var(--ink);\n  }\n  .aen2-hero h1 em {\n    font-style: normal;\n    color: var(--brand);\n  }\n\n  .aen2-hero p.aen2-sub {\n    font-weight: 400;\n    font-size: 1.08rem;\n    line-height: 2;\n    color: var(--muted);\n    max-width: 32rem;\n    margin: 0 0 2rem;\n  }\n\n  .aen2-cta-row { display: flex; gap: 0.85rem; flex-wrap: wrap; margin-bottom: 2.6rem; }\n\n  .aen2-btn {\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.96rem;\n    padding: 0.9rem 1.8rem;\n    border-radius: 10px;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    transition: transform .15s ease, box-shadow .15s ease, background .15s ease;\n  }\n  .aen2-btn--primary {\n    background: var(--brand);\n    color: #fff;\n    box-shadow: 0 10px 24px -8px rgba(21,154,91,0.55);\n  }\n  .aen2-btn--primary:hover { background: var(--brand-deep); transform: translateY(-2px); }\n  .aen2-btn--ghost {\n    background: #fff;\n    color: var(--ink);\n    border: 1px solid var(--line);\n  }\n  .aen2-btn--ghost:hover { border-color: var(--brand); color: var(--brand-deep); }\n\n  /* --- نکته کلیدی برند: سازگاری با هر شارژر --- */\n  .aen2-compat {\n    display: flex;\n    align-items: center;\n    gap: 0.7rem;\n    font-size: 0.88rem;\n    color: var(--muted);\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  .aen2-compat b { color: var(--ink); font-weight: 700; }\n  .aen2-compat .aen2-dot {\n    width: 6px; height: 6px; border-radius: 50%; background: var(--brand);\n  }\n\n  /* --- signature element: موکاپ داشبورد شارژ --- */\n  .aen2-visual {\n    position: relative;\n    width: 100%;\n    max-width: 440px;\n    height: 460px;\n    margin-inline-start: auto;\n  }\n\n  .aen2-card {\n    position: absolute;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: 18px;\n    box-shadow: 0 20px 50px -20px rgba(15,42,30,0.18);\n    padding: 1.4rem;\n  }\n\n  .aen2-card--main {\n    width: 320px;\n    max-width: 78%;\n    top: 0;\n    right: 0;\n    z-index: 2;\n  }\n  .aen2-card--main .aen2-row-head {\n    display: flex; justify-content: space-between; align-items: center;\n    margin-bottom: 1.1rem;\n  }\n  .aen2-card--main .aen2-status {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.3rem 0.7rem; border-radius: 999px;\n  }\n  .aen2-pulse {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--brand);\n    box-shadow: 0 0 0 0 rgba(21,154,91,0.5);\n    animation: aen2Pulse 1.8s infinite;\n  }\n  @keyframes aen2Pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(21,154,91,0.45); }\n    70%  { box-shadow: 0 0 0 8px rgba(21,154,91,0); }\n    100% { box-shadow: 0 0 0 0 rgba(21,154,91,0); }\n  }\n\n  .aen2-metric-row { display: flex; gap: 1rem; margin-bottom: 1.1rem; }\n  .aen2-metric {\n    flex: 1; background: #F6F9F7; border-radius: 12px; padding: 0.85rem 1rem;\n  }\n  .aen2-metric span { display: block; font-size: 0.74rem; color: var(--muted); margin-bottom: 0.25rem; }\n  .aen2-metric b { font-size: 1.15rem; color: var(--ink); }\n\n  .aen2-bar-track { height: 8px; background: #EDF2EF; border-radius: 999px; overflow: hidden; margin-bottom: 0.5rem; }\n  .aen2-bar-fill {\n    height: 100%; width: 68%; border-radius: 999px;\n    background: linear-gradient(90deg, var(--brand-deep), var(--brand));\n    animation: aen2Fill 2.4s ease-out;\n  }\n  @keyframes aen2Fill { from { width: 0%; } to { width: 68%; } }\n  .aen2-bar-caption { display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--muted); }\n\n  .aen2-card--floating {\n    width: 220px;\n    max-width: 60%;\n    left: 0;\n    bottom: 0;\n    z-index: 3;\n  }\n  .aen2-card--floating .aen2-fl-title { font-size: 0.8rem; color: var(--muted); margin-bottom: 0.5rem; }\n  .aen2-card--floating .aen2-fl-amount { font-size: 1.35rem; font-weight: 800; color: var(--ink); }\n  .aen2-card--floating .aen2-fl-amount small { font-size: 0.85rem; font-weight: 500; color: var(--muted); }\n  .aen2-card--floating .aen2-fl-tag {\n    display: inline-block; margin-top: 0.6rem;\n    font-size: 0.72rem; font-weight: 700; color: var(--brand-deep);\n    background: var(--brand-soft); padding: 0.2rem 0.55rem; border-radius: 6px;\n  }\n\n  @media (max-width: 900px) {\n    .aen2-grid { grid-template-columns: 1fr; text-align: center; }\n    .aen2-cta-row, .aen2-compat { justify-content: center; }\n    .aen2-visual {\n      order: -1;\n      position: static;\n      height: auto;\n      max-width: 320px;\n      margin: 0 auto 1.6rem;\n      display: flex;\n      flex-direction: column;\n      gap: 1rem;\n    }\n    .aen2-card {\n      position: static;\n      width: 100% !important;\n      max-width: 100% !important;\n    }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen2-hero\">\n  <div class=\"aen2-grid\">\n\n    <div class=\"aen2-text\">\n      <span class=\"aen2-badge\">پلتفرم نرم‌افزاری شارژ خودروی برقی</span>\n\n      <h1>هر شارژری دارید،<br>با <em>نرم‌افزار آبان</em> هوشمندش کنید</h1>\n\n      <p class=\"aen2-sub\">\n        آبان انرژی نوا فقط شارژر نمی‌فروشد؛ یک پلتفرم کامل مدیریت شارژ ارائه می‌دهد —\n        از مانیتورینگ آنلاین و کیف پول تا اتصال شارژرهای دیگر شرکت‌ها به سامانه ما.\n      </p>\n\n      <div class=\"aen2-cta-row\">\n        <a href=\"/start-charging/\" class=\"aen2-btn aen2-btn--primary\">شروع شارژ →</a>\n        <a href=\"#\" class=\"aen2-btn aen2-btn--ghost\">اتصال شارژر شما به سامانه</a>\n      </div>\n\n      <div class=\"aen2-compat\">\n        <span class=\"aen2-dot\"></span>\n        <span><b>سازگار با استاندارد OCPP</b> — شارژر ما یا شارژر شما، فرقی نمی‌کند</span>\n      </div>\n    </div>\n\n    <div class=\"aen2-visual\">\n      <div class=\"aen2-card aen2-card--main\">\n        <div class=\"aen2-row-head\">\n          <strong>برج مرکزی001</strong>\n          <span class=\"aen2-status\"><span class=\"aen2-pulse\"></span> در حال شارژ</span>\n        </div>\n        <div class=\"aen2-metric-row\">\n          <div class=\"aen2-metric\"><span>انرژی</span><b>18.4 kWh</b></div>\n          <div class=\"aen2-metric\"><span>هزینه</span><b>142,000 ت</b></div>\n        </div>\n        <div class=\"aen2-bar-track\"><div class=\"aen2-bar-fill\"></div></div>\n        <div class=\"aen2-bar-caption\"><span>68٪ شارژ شده</span><span>باقی‌مانده ۲۲ دقیقه</span></div>\n      </div>\n\n      <div class=\"aen2-card aen2-card--floating\">\n        <div class=\"aen2-fl-title\">موجودی کیف پول</div>\n        <div class=\"aen2-fl-amount\">350,000 <small>تومان</small></div>\n        <span class=\"aen2-fl-tag\">تراکنش موفق ✓</span>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک ویژگی‌ها — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen3-features {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --bg: #F4F7F5;\n    --card: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen3-features * { box-sizing: border-box; }\n\n  .aen3-head {\n    max-width: 1180px;\n    margin: 0 auto 2.6rem;\n    text-align: center;\n  }\n  .aen3-head span.aen3-eyebrow {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .aen3-head h2 {\n    font-weight: 800;\n    font-size: clamp(1.5rem, 2.6vw, 2.1rem);\n    color: var(--ink);\n    margin: 0;\n  }\n\n  .aen3-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.4rem;\n  }\n\n  .aen3-card {\n    background: var(--card);\n    border-radius: 16px;\n    padding: 2.1rem 1.6rem;\n    text-align: center;\n    box-shadow: 0 2px 0 rgba(15,42,30,0.04);\n    transition: transform .18s ease, box-shadow .18s ease;\n  }\n  .aen3-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 18px 34px -18px rgba(15,42,30,0.25);\n  }\n\n  .aen3-icon {\n    width: 56px;\n    height: 56px;\n    margin: 0 auto 1.2rem;\n    border-radius: 14px;\n    background: var(--brand-soft);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .aen3-icon svg { width: 26px; height: 26px; stroke: var(--brand-deep); }\n\n  .aen3-card h3 {\n    font-weight: 700;\n    font-size: 1.05rem;\n    color: var(--ink);\n    margin: 0 0 0.7rem;\n  }\n  .aen3-card p {\n    font-weight: 400;\n    font-size: 0.92rem;\n    line-height: 1.9;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  @media (max-width: 980px) {\n    .aen3-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 560px) {\n    .aen3-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen3-features\">\n  <div class=\"aen3-head\">\n    <span class=\"aen3-eyebrow\">چرا آبان انرژی نوا</span>\n    <h2>هر آنچه از یک پلتفرم شارژ نیاز دارید</h2>\n  </div>\n\n  <div class=\"aen3-grid\">\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M4 14v-2a8 8 0 0 1 16 0v2\"/>\n          <rect x=\"2\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n          <rect x=\"16\" y=\"14\" width=\"6\" height=\"6\" rx=\"1.5\"/>\n        </svg>\n      </div>\n      <h3>پشتیبانی ۲۴/۷</h3>\n      <p>تیم فنی آبان به‌صورت شبانه‌روزی پاسخ‌گوی مشکلات شارژر و نرم‌افزار شماست.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3z\"/>\n          <path d=\"M9 12l2 2 4-4\"/>\n        </svg>\n      </div>\n      <h3>امنیت تراکنش و شارژ</h3>\n      <p>پرداخت و کیف پول با بالاترین سطح امنیت، و قطع خودکار شارژ در صورت هر خطا.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M9 7H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h4\"/>\n          <path d=\"M15 7h4a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2h-4\"/>\n          <path d=\"M9 12h6\"/>\n          <path d=\"M13 9l3 3-3 3\"/>\n        </svg>\n      </div>\n      <h3>سازگار با هر شارژر</h3>\n      <p>چه شارژر آبان داشته باشید چه برندهای دیگر، با استاندارد OCPP به سامانه ما وصل می‌شوند.</p>\n    </div>\n\n    <div class=\"aen3-card\">\n      <div class=\"aen3-icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/>\n          <path d=\"M8 21h8\"/>\n          <path d=\"M12 17v4\"/>\n          <path d=\"M7 13l3-3 2.5 2.5L17 8\"/>\n        </svg>\n      </div>\n      <h3>مانیتورینگ آنلاین</h3>\n      <p>وضعیت هر ایستگاه، مصرف انرژی و تراکنش‌ها را لحظه‌به‌لحظه از داشبورد خود ببینید.</p>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!-- ===================================================================\n     بلاک درباره ما v2 — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen5-about {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    padding: 5vw 6vw;\n    box-sizing: border-box;\n  }\n  .aen5-about * { box-sizing: border-box; }\n\n  .aen5-grid {\n    max-width: 1180px;\n    margin: 0 auto;\n    display: grid;\n    grid-template-columns: 1.25fr 0.75fr;\n    gap: 3.5rem;\n    align-items: start;\n  }\n\n  .aen5-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    background: var(--brand-soft);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.2rem;\n  }\n\n  .aen5-about h2 {\n    font-weight: 800;\n    font-size: clamp(1.6rem, 2.8vw, 2.3rem);\n    line-height: 1.4;\n    color: var(--ink);\n    margin: 0 0 1.4rem;\n  }\n\n  .aen5-about p {\n    font-weight: 400;\n    font-size: 1rem;\n    line-height: 2.05;\n    color: var(--muted);\n    margin: 0 0 1.3rem;\n  }\n  .aen5-about p:last-of-type { margin-bottom: 0; }\n  .aen5-about p strong { color: var(--ink); font-weight: 700; }\n\n  /* --- signature element: مسیر رشد (تایم‌لاین عمودی) --- */\n  .aen5-path {\n    position: sticky;\n    top: 2rem;\n    padding-inline-start: 2.6rem;\n  }\n\n  .aen5-path-track {\n    position: relative;\n  }\n\n  .aen5-path-line {\n    position: absolute;\n    inset-inline-start: -2.05rem;\n    top: 6px;\n    bottom: 6px;\n    width: 2px;\n    background: var(--line);\n  }\n  .aen5-path-line::after {\n    content: \"\";\n    position: absolute;\n    inset-inline-start: 0;\n    top: 0;\n    width: 100%;\n    height: 0%;\n    background: var(--brand);\n    animation: aen5Grow 2.2s ease-out forwards;\n    animation-delay: .2s;\n  }\n  @keyframes aen5Grow { to { height: 100%; } }\n\n  .aen5-step {\n    position: relative;\n    padding-bottom: 2.2rem;\n  }\n  .aen5-step:last-child { padding-bottom: 0; }\n\n  .aen5-dot {\n    position: absolute;\n    inset-inline-start: -2.6rem;\n    top: 2px;\n    width: 16px;\n    height: 16px;\n    border-radius: 50%;\n    background: #fff;\n    border: 3px solid var(--brand);\n    box-shadow: 0 0 0 4px #fff;\n  }\n  .aen5-step:last-child .aen5-dot {\n    background: var(--brand);\n    box-shadow: 0 0 0 4px #fff, 0 0 0 8px var(--brand-soft);\n  }\n\n  .aen5-step b {\n    display: block;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--brand-deep);\n    letter-spacing: 0.02em;\n    margin-bottom: 0.3rem;\n  }\n  .aen5-step span {\n    display: block;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.7;\n  }\n\n  @media (max-width: 900px) {\n    .aen5-grid { grid-template-columns: 1fr; }\n    .aen5-path { position: static; padding-inline-start: 2.4rem; margin-top: 2rem; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<section class=\"aen5-about\">\n  <div class=\"aen5-grid\">\n\n    <div class=\"aen5-text\">\n      <span class=\"aen5-badge\">درباره ما</span>\n      <h2>درباره ما</h2>\n\n      <p>\n        آبان انرژی نوا فعالیت خود را در سال ۱۴۰۴ با هدف توسعه زیرساخت‌های هوشمند شارژ\n        خودروهای برقی آغاز کرد. مسیر ما از تأمین و عرضه شارژرهای <strong>AC 22kW</strong>\n        شروع شد، اما امروز تمرکز اصلی ما بر بومی‌سازی فناوری شارژ و توسعه راهکارهای\n        نرم‌افزاری برای مدیریت شارژرهای خودروهای برقی است.\n      </p>\n\n      <p>\n        ما باور داریم که کاربران نباید برای استفاده از یک نرم‌افزار مناسب، به یک برند\n        خاص از شارژر محدود شوند. به همین دلیل، پلتفرم هوشمند آبان طراحی شده تا تمام\n        شارژرهای سازگار با استاندارد <strong>OCPP</strong> را به یک سامانه یکپارچه متصل\n        کند؛ بدون توجه به برند یا تولیدکننده آن.\n      </p>\n\n      <p>\n        با اتصال شارژر به پلتفرم آبان، امکاناتی مانند پرداخت آنلاین، کیف پول، مشاهده\n        وضعیت و زمان شارژ به‌صورت لحظه‌ای، گزارش‌گیری، مدیریت ایستگاه‌ها و پشتیبانی\n        نرم‌افزاری ۲۴ ساعته در اختیار کاربران و کسب‌وکارها قرار می‌گیرد.\n      </p>\n\n      <p>\n        ما در آبان انرژی نوا تنها یک تأمین‌کننده تجهیزات نیستیم؛ بلکه در حال ساخت\n        زیرساختی هستیم که تجربه شارژ خودروهای برقی را هوشمندتر، ساده‌تر و در\n        دسترس‌تر کند.\n      </p>\n    </div>\n\n    <div class=\"aen5-path\">\n      <div class=\"aen5-path-track\">\n        <div class=\"aen5-path-line\"></div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>۱۴۰۴</b>\n          <span>تأمین و عرضه شارژرهای AC 22kW</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام دوم</b>\n          <span>بومی‌سازی فناوری و توسعه نرم‌افزار مدیریت شارژ</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>گام سوم</b>\n          <span>اتصال شارژرهای هر برند با استاندارد OCPP</span>\n        </div>\n\n        <div class=\"aen5-step\">\n          <span class=\"aen5-dot\"></span>\n          <b>امروز</b>\n          <span>زیرساخت یکپارچه‌ی شارژ هوشمند</span>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'خانه', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-08-03 14:47:30', '2026-08-03 11:17:30', '', 15, 'https://abanenergynova.ir/?p=400', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(401, 1, '2026-08-03 15:25:37', '2026-08-03 11:55:37', '{\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- ===================================================================\\n     \\u0641\\u0648\\u062a\\u0631 \\u2014 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627\\n     \\u0646\\u062d\\u0648\\u0647 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647: \\u06a9\\u0644 \\u0627\\u06cc\\u0646 \\u06a9\\u062f \\u0631\\u0648 \\u062f\\u0627\\u062e\\u0644 \\u06cc\\u06a9 \\u0648\\u06cc\\u062c\\u062a \\\"HTML\\\" \\u062f\\u0631 Elementor \\u06cc\\u0627\\n     \\u0628\\u0644\\u0627\\u06a9 \\\"Custom HTML\\\" \\u062f\\u0631 \\u06af\\u0648\\u062a\\u0646\\u0628\\u0631\\u06af \\u067e\\u06cc\\u0633\\u062a \\u06a9\\u0646 (\\u067e\\u0627\\u06cc\\u06cc\\u0646\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0628\\u0644\\u0627\\u06a9 \\u0635\\u0641\\u062d\\u0647).\\n     \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b self-contained \\u0627\\u0633\\u062a.\\n==================================================================== -->\\n\\n<style>\\n  .aen6-footer {\\n    --ink: #0F2A1E;\\n    --muted: #9FB3A8;\\n    --line: rgba(244,247,245,0.12);\\n    --bg: #0B1F17;\\n    --brand: #159A5B;\\n    --brand-bright: #4CD787;\\n    --off: #F4F7F5;\\n\\n    direction: rtl;\\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\\n    background: var(--bg);\\n    color: var(--off);\\n    padding: 4vw 6vw 2vw;\\n    box-sizing: border-box;\\n  }\\n  .aen6-footer * { box-sizing: border-box; }\\n\\n  .aen6-top {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    display: grid;\\n    grid-template-columns: 1.2fr 0.8fr 1fr 1fr;\\n    gap: 2.4rem;\\n    padding-bottom: 2.6rem;\\n  }\\n\\n  .aen6-brand-name {\\n    font-weight: 800;\\n    font-size: 1.15rem;\\n    color: var(--off);\\n    margin: 0 0 0.9rem;\\n  }\\n  .aen6-brand-name span { color: var(--brand-bright); }\\n\\n  .aen6-top p.aen6-desc {\\n    font-size: 0.9rem;\\n    line-height: 1.9;\\n    color: var(--muted);\\n    margin: 0;\\n    max-width: 22rem;\\n  }\\n\\n  .aen6-col h4 {\\n    font-size: 0.92rem;\\n    font-weight: 700;\\n    color: var(--off);\\n    margin: 0 0 1.1rem;\\n  }\\n\\n  .aen6-col ul {\\n    list-style: none;\\n    margin: 0;\\n    padding: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.75rem;\\n  }\\n  .aen6-col a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    font-size: 0.88rem;\\n    transition: color .15s ease;\\n  }\\n  .aen6-col a:hover { color: var(--brand-bright); }\\n\\n  .aen6-col .aen6-cta a {\\n    color: var(--brand-bright);\\n    font-weight: 700;\\n  }\\n\\n  .aen6-contact li {\\n    font-size: 0.88rem;\\n    color: var(--muted);\\n    line-height: 1.85;\\n  }\\n  .aen6-contact li b {\\n    display: block;\\n    color: var(--off);\\n    font-weight: 700;\\n    font-size: 0.85rem;\\n    margin-bottom: 0.15rem;\\n  }\\n  .aen6-contact li a {\\n    color: var(--muted);\\n    text-decoration: none;\\n    direction: ltr;\\n    display: inline-block;\\n  }\\n  .aen6-contact li a:hover { color: var(--brand-bright); }\\n\\n  .aen6-bottom {\\n    max-width: 1180px;\\n    margin: 0 auto;\\n    border-top: 1px solid var(--line);\\n    padding-top: 1.4rem;\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    flex-wrap: wrap;\\n    gap: 0.8rem;\\n    font-size: 0.8rem;\\n    color: var(--muted);\\n  }\\n\\n  @media (max-width: 900px) {\\n    .aen6-top { grid-template-columns: 1fr 1fr; }\\n  }\\n  @media (max-width: 560px) {\\n    .aen6-top { grid-template-columns: 1fr; text-align: center; }\\n    .aen6-top p.aen6-desc { max-width: 100%; margin: 0 auto; }\\n    .aen6-col ul { align-items: center; }\\n    .aen6-bottom { justify-content: center; text-align: center; }\\n  }\\n</style>\\n\\n<link rel=\\\"preconnect\\\" href=\\\"https://fonts.googleapis.com\\\">\\n<link href=\\\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&amp;display=swap\\\" rel=\\\"stylesheet\\\">\\n\\n<footer class=\\\"aen6-footer\\\">\\n  <div class=\\\"aen6-top\\\">\\n\\n    <div class=\\\"aen6-brand\\\">\\n      <div class=\\\"aen6-brand-name\\\">\\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc <span>\\u0646\\u0648\\u0627</span></div>\\n      <p class=\\\"aen6-desc\\\">\\n        \\u062a\\u0648\\u0644\\u06cc\\u062f\\u060c \\u0648\\u0627\\u0631\\u062f\\u0627\\u062a \\u0648 \\u0646\\u0635\\u0628 \\u0634\\u0627\\u0631\\u0698\\u0631\\u0647\\u0627\\u06cc \\u062e\\u0648\\u062f\\u0631\\u0648\\u06cc \\u0628\\u0631\\u0642\\u06cc\\u060c \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0644\\u062a\\u0641\\u0631\\u0645 \\u0646\\u0631\\u0645\\u200c\\u0627\\u0641\\u0632\\u0627\\u0631\\u06cc\\n        \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0634\\u0627\\u0631\\u0698 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0628\\u0627 \\u0627\\u0633\\u062a\\u0627\\u0646\\u062f\\u0627\\u0631\\u062f OCPP.\\n      </p>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u0633\\u0631\\u06cc\\u0639</h4>\\n      <ul>\\n        <li><a href=\\\"/\\\">\\u062e\\u0627\\u0646\\u0647</a></li>\\n        <li class=\\\"aen6-cta\\\"><a href=\\\"/start-charging/\\\">\\u0634\\u0631\\u0648\\u0639 \\u0634\\u0627\\u0631\\u0698\\u0631</a></li>\\n        <li><a href=\\\"#\\\">\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0634\\u0627\\u0631\\u0698\\u0631 \\u0634\\u0645\\u0627</a></li>\\n        <li><a href=\\\"/contact/\\\">\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</a></li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u062a\\u0645\\u0627\\u0633 \\u0628\\u0627 \\u0645\\u0627</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u062a\\u0644\\u0641\\u0646</b>\\n          <a href=\\\"tel:+982166649792\\\">021 66649792</a>\\n        </li>\\n        <li>\\n          <b>\\u0641\\u0631\\u0648\\u0634</b>\\n          <a href=\\\"tel:+989193341696\\\">0919 334 1696</a>\\n        </li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\\"aen6-col\\\">\\n      <h4>\\u0622\\u062f\\u0631\\u0633 \\u0648 \\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</h4>\\n      <ul class=\\\"aen6-contact\\\">\\n        <li>\\n          <b>\\u0622\\u062f\\u0631\\u0633</b>\\n          \\u0645\\u0647\\u0631\\u0622\\u0628\\u0627\\u062f \\u062c\\u0646\\u0648\\u0628\\u06cc\\u060c \\u062e\\u06cc\\u0627\\u0628\\u0627\\u0646 \\u06a9\\u0648\\u0633\\u0647\\u200c\\u0644\\u0648\\u060c \\u062a\\u0647\\u0631\\u0627\\u0646\\u060c \\u0627\\u06cc\\u0631\\u0627\\u0646\\n        </li>\\n        <li>\\n          <b>\\u0633\\u0627\\u0639\\u062a \\u06a9\\u0627\\u0631\\u06cc</b>\\n          \\u0634\\u0646\\u0628\\u0647 \\u062a\\u0627 \\u0686\\u0647\\u0627\\u0631\\u0634\\u0646\\u0628\\u0647\\u060c \\u06f8 \\u062a\\u0627 \\u06f1\\u06f6\\n        </li>\\n      </ul>\\n    </div>\\n\\n  </div>\\n\\n  <div class=\\\"aen6-bottom\\\">\\n    <span>\\u00a9 \\u06f1\\u06f4\\u06f0\\u06f5 \\u0622\\u0628\\u0627\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0646\\u0648\\u0627. \\u062a\\u0645\\u0627\\u0645\\u06cc \\u062d\\u0642\\u0648\\u0642 \\u0645\\u062d\\u0641\\u0648\\u0638 \\u0627\\u0633\\u062a.</span>\\n    <span>\\u0633\\u0627\\u062e\\u062a\\u0647\\u200c\\u0634\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647\\u200c\\u06cc \\u0634\\u0627\\u0631\\u0698 \\u0647\\u0648\\u0634\\u0645\\u0646\\u062f</span>\\n  </div>\\n</footer>\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-03 11:55:37\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '85abe4c3-3d94-4404-a57d-1ed0eab27f6f', '', '', '2026-08-03 15:25:37', '2026-08-03 11:55:37', '', 0, 'https://abanenergynova.ir/2026/08/03/85abe4c3-3d94-4404-a57d-1ed0eab27f6f/', 0, 'customize_changeset', '', 0),
(402, 1, '2026-08-03 15:30:43', '2026-08-03 12:00:43', '<!-- wp:html -->\n<!-- ===================================================================\n     صفحه \"شروع شارژ\" — راهنمای مراحل استفاده — آبان انرژی نوا\n     نحوه استفاده: کل این کد رو داخل یک ویجت \"HTML\" در Elementor یا\n     بلاک \"Custom HTML\" در گوتنبرگ (تو یه صفحه جدید به اسم \"شروع شارژ\")\n     پیست کن. کاملاً self-contained است.\n==================================================================== -->\n\n<style>\n  .aen7-guide {\n    --ink: #0F2A1E;\n    --muted: #5B6B63;\n    --line: #E3EAE5;\n    --bg: #FFFFFF;\n    --card: #F6F9F7;\n    --brand: #159A5B;\n    --brand-deep: #0E7A47;\n    --brand-soft: #E7F6ED;\n\n    direction: rtl;\n    font-family: \'Vazirmatn\', Tahoma, sans-serif;\n    background: var(--bg);\n    box-sizing: border-box;\n  }\n  .aen7-guide * { box-sizing: border-box; }\n\n  /* --- هدر صفحه --- */\n  .aen7-hero {\n    background: radial-gradient(120% 160% at 20% 0%, #0F2A1E 0%, #0B1F17 60%);\n    color: #F4F7F5;\n    padding: 4.5vw 6vw;\n    text-align: center;\n  }\n  .aen7-hero span.aen7-badge {\n    display: inline-block;\n    font-size: 0.82rem;\n    font-weight: 700;\n    color: #4CD787;\n    background: rgba(76,215,135,0.1);\n    border: 1px solid rgba(76,215,135,0.25);\n    padding: 0.4rem 0.9rem;\n    border-radius: 999px;\n    margin-bottom: 1.1rem;\n  }\n  .aen7-hero h1 {\n    font-weight: 800;\n    font-size: clamp(1.8rem, 3.2vw, 2.6rem);\n    margin: 0 0 0.9rem;\n    color: #F4F7F5 !important;\n    background: none !important;\n  }\n  .aen7-hero p {\n    font-size: 1rem;\n    line-height: 2;\n    color: #9FB3A8;\n    max-width: 38rem;\n    margin: 0 auto;\n  }\n\n  /* --- مراحل --- */\n  .aen7-steps {\n    max-width: 1080px;\n    margin: 0 auto;\n    padding: 5vw 6vw;\n  }\n\n  .aen7-steps-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 1.2rem;\n    position: relative;\n  }\n\n  .aen7-step {\n    position: relative;\n    background: var(--card);\n    border-radius: 16px;\n    padding: 1.8rem 1.4rem;\n    text-align: center;\n  }\n\n  .aen7-step-num {\n    width: 42px;\n    height: 42px;\n    margin: 0 auto 1.1rem;\n    border-radius: 50%;\n    background: var(--brand);\n    color: #fff;\n    font-weight: 800;\n    font-size: 1.05rem;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .aen7-step h3 {\n    font-size: 1rem;\n    font-weight: 700;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-step p {\n    font-size: 0.88rem;\n    line-height: 1.85;\n    color: var(--muted);\n    margin: 0;\n  }\n\n  .aen7-arrow {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--line);\n  }\n\n  /* --- بنر پایانی: به‌زودی --- */\n  .aen7-soon {\n    max-width: 1080px;\n    margin: 0 auto 5vw;\n    padding: 0 6vw;\n  }\n  .aen7-soon-box {\n    background: var(--brand-soft);\n    border: 1px solid rgba(21,154,91,0.2);\n    border-radius: 18px;\n    padding: 2.2rem 2rem;\n    text-align: center;\n  }\n  .aen7-soon-box h2 {\n    font-size: 1.2rem;\n    font-weight: 800;\n    color: var(--ink);\n    margin: 0 0 0.6rem;\n  }\n  .aen7-soon-box p {\n    font-size: 0.95rem;\n    color: var(--muted);\n    line-height: 1.9;\n    max-width: 32rem;\n    margin: 0 auto 1.4rem;\n  }\n  .aen7-soon-box a {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n    background: var(--brand);\n    color: #fff;\n    text-decoration: none;\n    font-weight: 700;\n    font-size: 0.94rem;\n    padding: 0.85rem 1.8rem;\n    border-radius: 10px;\n    transition: background .15s ease, transform .15s ease;\n  }\n  .aen7-soon-box a:hover { background: var(--brand-deep); transform: translateY(-2px); }\n\n  @media (max-width: 900px) {\n    .aen7-steps-grid { grid-template-columns: 1fr 1fr; }\n    .aen7-arrow { display: none; }\n  }\n  @media (max-width: 560px) {\n    .aen7-steps-grid { grid-template-columns: 1fr; }\n  }\n</style>\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<div class=\"aen7-guide\">\n\n  <section class=\"aen7-hero\">\n    <span class=\"aen7-badge\">راهنمای شارژ</span>\n    <h1>شارژ کردن با آبان، در ۴ قدم ساده</h1>\n    <p>\n      وقتی پلتفرم آبان روی ایستگاه شارژ شما فعال باشد، رساندن خودرو به شارژ کامل\n      دیگر نیازی به کارت یا اپراتور جداگانه ندارد.\n    </p>\n  </section>\n\n  <section class=\"aen7-steps\">\n    <div class=\"aen7-steps-grid\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۱</div>\n        <h3>پیدا کردن ایستگاه</h3>\n        <p>نزدیک‌ترین ایستگاه فعال آبان را از روی نقشه یا لیست ایستگاه‌ها پیدا کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۲</div>\n        <h3>انتخاب دستگاه</h3>\n        <p>کد دستگاه را اسکن یا از لیست انتخاب کنید تا وضعیت آن را ببینید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n\n    <div class=\"aen7-steps-grid\" style=\"margin-top: 1.2rem;\">\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۳</div>\n        <h3>اتصال کابل</h3>\n        <p>کابل شارژ را به خودروی خود وصل کنید و شارژ را از داشبورد شروع کنید.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n      <div class=\"aen7-step\">\n        <div class=\"aen7-step-num\">۴</div>\n        <h3>پرداخت از کیف پول</h3>\n        <p>هزینه شارژ خودکار از کیف پول کسر می‌شود؛ رسید هم همان لحظه صادر می‌شود.</p>\n      </div>\n\n      <div class=\"aen7-arrow\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" style=\"opacity:0\"><path d=\"M15 6l-6 6 6 6\"/></svg>\n      </div>\n\n    </div>\n  </section>\n\n  <section class=\"aen7-soon\">\n    <div class=\"aen7-soon-box\">\n      <h2>پلتفرم شارژ آبان به‌زودی راه‌اندازی می‌شود</h2>\n      <p>\n        در حال حاضر در حال راه‌اندازی زیرساخت نرم‌افزاری هستیم. برای اطلاع از زمان\n        فعال‌سازی ایستگاه‌ها یا هماهنگی نصب شارژر، با ما در تماس باشید.\n      </p>\n      <a href=\"/contact/\">تماس با ما ←</a>\n    </div>\n  </section>\n\n</div>\n<!-- /wp:html -->', 'شروع شارژ', '', 'inherit', 'closed', 'closed', '', '2-revision-v1', '', '', '2026-08-03 15:30:43', '2026-08-03 12:00:43', '', 2, 'https://abanenergynova.ir/?p=402', 0, 'revision', '', 0);
